    {"german_text": 'Die Firma bietet Weiterbildungen an.', "english_translation": 'The company offers further training.', "arabic_translation": 'الشركة تقدم تدريبًا إضافيًا.', "level": 'A2', "difficulty_score": 4, "category": 'Work'},
