    {"german_text": 'Ich habe Halsschmerzen heute.', "english_translation": 'I have a sore throat today.', "arabic_translation": 'أنا لدي آلام في الحلق اليوم.', "level": 'A2', "difficulty_score": 3, "category": 'Health'},
    {"german_text": 'Der Arzt verschreibt mir ein Medikament.', "english_translation": 'The doctor prescribes me a medication.', "arabic_translation": 'الطبيب يصف لي دواءً.', "level": 'A2', "difficulty_score": 3, "category": 'Health'},
