    {"german_text": 'Ich habe mich beim Joggen verletzt.', "english_translation": 'I injured myself while jogging.', "arabic_translation": 'أنا أصبت نفسي أثناء الهرولة.', "level": 'A2', "difficulty_score": 4, "category": 'Health'},
