    {"german_text": 'Ich nehme Vitamine jeden Morgen.', "english_translation": 'I take vitamins every morning.', "arabic_translation": 'أنا آخذ الفيتامينات كل صباح.', "level": 'A2', "difficulty_score": 3, "category": 'Health'},
