    {"german_text": 'Ich züchte meinen eigenen Gemüse im Garten.', "english_translation": 'I grow my own vegetables in the garden.', "arabic_translation": 'أنا أزرع خضرواتي الخاصة في الحديقة.', "level": 'A2', "difficulty_score": 4, "category": 'Environment'},
    {"german_text": 'Ich vermeide Lebensmittelverschwendung.', "english_translation": 'I avoid food waste.', "arabic_translation": 'أنا أتجنب هدر الطعام.', "level": 'A2', "difficulty_score": 4, "category": 'Environment'},
    {"german_text": 'Ich wähle bei der Bundestagswahl.', "english_translation": 'I vote in the federal election.', "arabic_translation": 'أنا أصوت في الانتخابات الفيدرالية.', "level": 'A2', "difficulty_score": 4, "category": 'Politics'},
