    {"german_text": 'Die Demonstranten fordern Klimaschutz.', "english_translation": 'The demonstrators demand climate protection.', "arabic_translation": 'المتظاهرون يطالبون بحماية المناخ.', "level": 'A2', "difficulty_score": 5, "category": 'Politics'},
