    {"german_text": 'Die Wissenschaft macht große Fortschritte.', "english_translation": 'Science is making great progress.', "arabic_translation": 'العلم يحقق تقدمًا كبيرًا.', "level": 'A2', "difficulty_score": 4, "category": 'Science'},
    {"german_text": 'Ich probiere ein Experiment im Labor aus.', "english_translation": 'I try out an experiment in the lab.', "arabic_translation": 'أنا أجرب تجربة في المختبر.', "level": 'A2', "difficulty_score": 4, "category": 'Science'},
