    {"german_text": 'Ich diskutiere über Determinismus und Freiheit.', "english_translation": 'I discuss determinism and freedom.', "arabic_translation": 'أنا أناقش الحتمية والحرية.', "level": 'A2', "difficulty_score": 5, "category": 'Philosophy'},
    {"german_text": 'Die Vernunft unterscheidet den Menschen vom Tier.', "english_translation": 'Reason distinguishes man from animal.', "arabic_translation": 'العقل يميز الإنسان عن الحيوان.', "level": 'A2', "difficulty_score": 4, "category": 'Philosophy'},
    {"german_text": 'Ich philosophiere über die Zukunft der Menschheit.', "english_translation": 'I philosophize about the future of mankind.', "arabic_translation": 'أنا أتفلسف عن مستقبل البشرية.', "level": 'A2', "difficulty_score": 5, "category": 'Philosophy'},
