    {"german_text": 'Ich habe einen Online-Kurs abgeschlossen.', "english_translation": 'I completed an online course.', "arabic_translation": 'أكملت دورة عبر الإنترنت.', "level": 'B1', "difficulty_score": 5, "category": 'Education'},
