    {"german_text": 'Ich habe ein Backup meiner Daten gemacht.', "english_translation": 'I made a backup of my data.', "arabic_translation": 'قمت بنسخ بياناتي احتياطيًا.', "level": 'B1', "difficulty_score": 6, "category": 'Technology'},
