    {"german_text": 'Der Klimawandel betrifft uns alle.', "english_translation": 'Climate change affects us all.', "arabic_translation": 'تغير المناخ يؤثر علينا جميعًا.', "level": 'B1', "difficulty_score": 5, "category": 'Environment'},
