    {"german_text": 'Ich kaufe nur noch regionale Produkte.', "english_translation": 'I only buy regional products now.', "arabic_translation": 'لا أشتري إلا المنتجات الإقليمية الآن.', "level": 'B1', "difficulty_score": 5, "category": 'Environment'},
