    {"german_text": 'Die Zusammenhänge sind komplex und nicht linear.', "english_translation": 'The connections are complex and not linear.', "arabic_translation": 'العلاقات معقدة وغير خطية.', "level": 'B2', "difficulty_score": 8, "category": 'Abstract'},
