    {"german_text": 'Die physikalische Therapie unterstützt die Heilung.', "english_translation": 'Physical therapy supports healing.', "arabic_translation": 'يدعم العلاج الطبيعي الشفاء.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Neurochirurgie hat neue Techniken entwickelt.', "english_translation": 'Neurosurgery has developed new techniques.', "arabic_translation": 'طور جراحة الأعصاب تقنيات جديدة.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Pharmakologie untersucht die Wirkung von Medikamenten.', "english_translation": 'Pharmacology examines the effects of medications.', "arabic_translation": 'يدرس علم الأدوية تأثير الأدوية.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Pathologie analysiert Gewebeproben.', "english_translation": 'Pathology analyzes tissue samples.', "arabic_translation": 'يحلل علم الأمراض عينات الأنسجة.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Radiologie nutzt bildgebende Verfahren.', "english_translation": 'Radiology uses imaging procedures.', "arabic_translation": 'يستخدم علم الأشعة إجراءات التصوير.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Anästhesie ermöglicht schmerzfreie Operationen.', "english_translation": 'Anesthesia enables painless surgeries.', "arabic_translation": 'يمكن التخدير عمليات بدون ألم.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Dermatologie behandelt Hauterkrankungen.', "english_translation": 'Dermatology treats skin diseases.', "arabic_translation": 'يعالج علم الأمراض الجلدية أمراض الجلد.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Kardiologie beschäftigt sich mit Herzerkrankungen.', "english_translation": 'Cardiology deals with heart diseases.', "arabic_translation": 'يتعامل علم القلب مع أمراض القلب.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Orthopädie behandelt Knochen- und Gelenkprobleme.', "english_translation": 'Orthopedics treats bone and joint problems.', "arabic_translation": 'يعالج جراحة العظام مشاكل العظام والمفاصل.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die pädiatrische Versorgung ist spezialisiert.', "english_translation": 'Pediatric care is specialized.', "arabic_translation": 'الرعاية الأطفال متخصصة.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Geriatrie befasst sich mit altersbedingten Erkrankungen.', "english_translation": 'Geriatrics deals with age-related diseases.', "arabic_translation": 'يتعامل علم الشيخوخة مع الأمراض المرتبطة بالعمر.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Onkologie forscht an neuen Therapien.', "english_translation": 'Oncology researches new therapies.', "arabic_translation": 'يبحث علم الأورام في علاجات جديدة.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Immunologie untersucht das Abwehrsystem.', "english_translation": 'Immunology examines the defense system.', "arabic_translation": 'يدرس علم المناعة نظام الدفاع.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Endokrinologie behandelt Hormonstörungen.', "english_translation": 'Endocrinology treats hormone disorders.', "arabic_translation": 'يعالج علم الغدد الصماء اضطرابات الهرمونات.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Gastroenterologie befasst sich mit dem Verdauungssystem.', "english_translation": 'Gastroenterology deals with the digestive system.', "arabic_translation": 'يتعامل علم الجهاز الهضمي مع الجهاز الهضمي.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Pneumologie behandelt Lungenerkrankungen.', "english_translation": 'Pulmonology treats lung diseases.', "arabic_translation": 'يعالج علم الرئة أمراض الرئة.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Nephrologie beschäftigt sich mit den Nieren.', "english_translation": 'Nephrology deals with the kidneys.', "arabic_translation": 'يتعامل علم الكلى مع الكلى.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Urologie behandelt Erkrankungen der Harnwege.', "english_translation": 'Urology treats urinary tract diseases.', "arabic_translation": 'يعالج علم المسالك البولية أمراض الجهاز البولي.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Gynäkologie kümmert sich um Frauengesundheit.', "english_translation": "Gynecology takes care of women's health.", "arabic_translation": 'يهتم علم أمراض النساء بصحة المرأة.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Suchtmedizin bietet Unterstützung für Abhängige.', "english_translation": 'Addiction medicine offers support for addicts.', "arabic_translation": 'يقدم طب الإدمان الدعم للمدمنين.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Ernährungsmedizin gewinnt an Bedeutung.', "english_translation": 'Nutritional medicine is gaining importance.', "arabic_translation": 'يكتسب الطب الغذائي أهمية.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Sportmedizin untersucht die Auswirkungen von Bewegung.', "english_translation": 'Sports medicine examines the effects of exercise.', "arabic_translation": 'يدرس الطب الرياضي تأثيرات التمرين.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Reisemedizin berät vor Auslandsreisen.', "english_translation": 'Travel medicine advises before trips abroad.', "arabic_translation": 'ينصح طب السفر قبل الرحلات إلى الخارج.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Arbeitsmedizin befasst sich mit Gesundheit am Arbeitsplatz.', "english_translation": 'Occupational medicine deals with health at the workplace.', "arabic_translation": 'يتعامل الطب المهني مع الصحة في مكان العمل.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Hygienemaßnahmen wurden verschärft.', "english_translation": 'Hygiene measures were tightened.', "arabic_translation": 'تم تشديد إجراءات النظافة.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die Seuchenprävention ist eine globale Aufgabe.', "english_translation": 'Disease prevention is a global task.', "arabic_translation": 'الوقاية من الأمراض مهمة عالمية.', "level": 'B2', "difficulty_score": 7, "category": 'Medicine'},
    {"german_text": 'Die evidenzbasierte Medizin ist der Goldstandard.', "english_translation": 'Evidence-based medicine is the gold standard.', "arabic_translation": 'الطب القائم على الأدلة هو المعيار الذهبي.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die interdisziplinäre Zusammenarbeit verbessert die Behandlung.', "english_translation": 'Interdisciplinary cooperation improves treatment.', "arabic_translation": 'يحسن التعاون متعدد التخصصات العلاج.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Patientenverfügung regelt medizinische Maßnahmen im Voraus.', "english_translation": 'The advance directive regulates medical measures in advance.', "arabic_translation": 'ينظم التوجيه المسبق الإجراءات الطبية مسبقًا.', "level": 'B2', "difficulty_score": 8, "category": 'Medicine'},
    {"german_text": 'Die Pädagogik hat sich in den letzten Jahrzehnten gewandelt.', "english_translation": 'Pedagogy has changed in recent decades.', "arabic_translation": 'تغير علم التربية في العقود الأخيرة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Bildungsungleichheit ist ein gesellschaftliches Problem.', "english_translation": 'Educational inequality is a social problem.', "arabic_translation": 'عدم المساواة التعليمية مشكلة اجتماعية.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die digitale Bildung muss gefördert werden.', "english_translation": 'Digital education must be promoted.', "arabic_translation": 'يجب تعزيز التعليم الرقمي.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Lehrpläne werden regelmäßig aktualisiert.', "english_translation": 'The curricula are regularly updated.', "arabic_translation": 'تُحدث المناهج الدراسية بانتظام.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Früherziehung ist von großer Bedeutung.', "english_translation": 'Early education is of great importance.', "arabic_translation": 'التعليم المبكر ذو أهمية كبيرة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Sonderpädagogik unterstützt Kinder mit besonderen Bedürfnissen.', "english_translation": 'Special education supports children with special needs.', "arabic_translation": 'يدعم التعليم الخاص الأطفال ذوي الاحتياجات الخاصة.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Hochschulbildung ist für viele unerschwinglich.', "english_translation": 'Higher education is unaffordable for many.', "arabic_translation": 'التعليم العالي غير متاح للكثيرين.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Lehrerausbildung wurde reformiert.', "english_translation": 'Teacher training was reformed.', "arabic_translation": 'أُصلح تدريب المعلمين.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Bewertungssysteme sind umstritten.', "english_translation": 'The assessment systems are controversial.', "arabic_translation": 'أنظمة التقييم مثيرة للجدل.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Inklusion ist ein wichtiges Bildungsziel.', "english_translation": 'Inclusion is an important educational goal.', "arabic_translation": 'الشمول هدف تعليمي مهم.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Montessori-Pädagogik fördert selbstständiges Lernen.', "english_translation": 'Montessori pedagogy promotes independent learning.', "arabic_translation": 'يعزز منهج مونتيسوري التعلم المستقل.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Erwachsenenbildung gewinnt an Bedeutung.', "english_translation": 'Adult education is gaining importance.', "arabic_translation": 'يكتسب تعليم الكبار أهمية.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Forschung an Universitäten wird staatlich gefördert.', "english_translation": 'Research at universities is state-funded.', "arabic_translation": 'يمول البحث في الجامعات حكوميًا.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Bildungsstandards werden regelmäßig überprüft.', "english_translation": 'Educational standards are regularly reviewed.', "arabic_translation": 'تُراجع المعايير التعليمية بانتظام.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Schülerleistungen wurden evaluiert.', "english_translation": 'Student performance was evaluated.', "arabic_translation": 'تم تقييم أداء الطلاب.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Schulreife wird unterschiedlich definiert.', "english_translation": 'School readiness is defined differently.', "arabic_translation": 'يُعرف الاستعداد للمدرسة بشكل مختلف.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Ganztagsbetreuung wird ausgebaut.', "english_translation": 'All-day care is being expanded.', "arabic_translation": 'يتم توسيع الرعاية طوال اليوم.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Privatschulen haben unterschiedliche Konzepte.', "english_translation": 'Private schools have different concepts.', "arabic_translation": 'للمدارس الخاصة مفاهيم مختلفة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Berufsorientierung beginnt früh.', "english_translation": 'Career orientation begins early.', "arabic_translation": 'يبدأ التوجيه المهني مبكرًا.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die duale Ausbildung verbindet Praxis und Theorie.', "english_translation": 'Dual training combines practice and theory.', "arabic_translation": 'يجمع التدريب المزدوج بين الممارسة والنظرية.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Prüfungsordnung wurde geändert.', "english_translation": 'The examination regulations were changed.', "arabic_translation": 'تم تغيير لوائح الامتحان.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die akademische Freiheit ist ein Grundwert.', "english_translation": 'Academic freedom is a fundamental value.', "arabic_translation": 'الحرية الأكاديمية قيمة أساسية.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Promotion erfordert mehrere Jahre Forschung.', "english_translation": 'A doctorate requires several years of research.', "arabic_translation": 'يتطلب الدكتوراه عدة سنوات من البحث.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Habilitation ist die höchste akademische Qualifikation.', "english_translation": 'Habilitation is the highest academic qualification.', "arabic_translation": 'التأهيل هو أعلى مؤهل أكاديمي.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Postdoc-Phase ist oft unsicher.', "english_translation": 'The postdoc phase is often uncertain.', "arabic_translation": 'مرحلة ما بعد الدكتوراه غالبًا غير مؤكدة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Forschungsfinanzierung ist wettbewerbsintensiv.', "english_translation": 'Research funding is highly competitive.', "arabic_translation": 'تمويل البحث تنافسي للغاية.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Peer-Review-Verfahren sichern die Qualität.', "english_translation": 'Peer review processes ensure quality.', "arabic_translation": 'تضمن عمليات مراجعة الأقران الجودة.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Impact-Faktoren beeinflussen die Publikationswahl.', "english_translation": 'Impact factors influence publication choice.', "arabic_translation": 'تؤثر عوامل التأثير على اختيار النشر.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Open-Access-Bewegung gewinnt an Fahrt.', "english_translation": 'The open access movement is gaining momentum.', "arabic_translation": 'يكتسب حركة الوصول المفتوح زخمًا.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die E-Learning-Plattformen haben die Lehre verändert.', "english_translation": 'E-learning platforms have changed teaching.', "arabic_translation": 'غيرت منصات التعليم الإلكتروني التدريس.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Blended-Learning-Ansätze sind effektiv.', "english_translation": 'Blended learning approaches are effective.', "arabic_translation": 'نهج التعلم المدمج فعال.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Gamification steigert die Motivation.', "english_translation": 'Gamification increases motivation.', "arabic_translation": 'يزيد التلعيب من الدافع.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Lernanalyse hilft, Schwächen zu identifizieren.', "english_translation": 'Learning analytics helps identify weaknesses.', "arabic_translation": 'يساعد تحليل التعلم في تحديد نقاط الضعف.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Kompetenzorientierung ersetzt die Wissensvermittlung.', "english_translation": 'Competence orientation replaces knowledge transfer.', "arabic_translation": 'يحل التوجه نحو الكفاءة محل نقل المعرفة.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Formative Beurteilung fördert den Lernprozess.', "english_translation": 'Formative assessment promotes the learning process.', "arabic_translation": 'يعزز التقييم التكويني عملية التعلم.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die konstruktivistische Didaktik ist modern.', "english_translation": 'Constructivist didactics is modern.', "arabic_translation": 'الديداكتيكا البنائية حديثة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Binnendifferenzierung berücksichtigt individuelle Bedürfnisse.', "english_translation": 'Internal differentiation takes individual needs into account.', "arabic_translation": 'يأخذ التمايز الداخلي في الاعتبار الاحتياجات الفردية.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Projektarbeit fördert das kritische Denken.', "english_translation": 'Project work promotes critical thinking.', "arabic_translation": 'يعزز العمل بالمشاريع التفكير النقدي.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Interkulturelle Kompetenz wird immer wichtiger.', "english_translation": 'Intercultural competence is becoming increasingly important.', "arabic_translation": 'تزداد أهمية الكفاءة بين الثقافات.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Bildungspolitik muss nachhaltig gestaltet werden.', "english_translation": 'Education policy must be designed sustainably.', "arabic_translation": 'يجب تصميم السياسة التعليمية بشكل مستدام.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Schulverwaltung ist komplex.', "english_translation": 'School administration is complex.', "arabic_translation": 'إدارة المدرسة معقدة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Elternmitwirkung ist erwünscht.', "english_translation": 'Parent involvement is desired.', "arabic_translation": 'مشاركة الوالدين مرغوبة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Schulentwicklung ist ein kontinuierlicher Prozess.', "english_translation": 'School development is a continuous process.', "arabic_translation": 'تطوير المدرسة عملية مستمرة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Qualitätssicherung im Bildungsbereich ist wichtig.', "english_translation": 'Quality assurance in education is important.', "arabic_translation": 'ضمان الجودة في مجال التعليم مهم.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Lehrergesundheit ist ein vernachlässigtes Thema.', "english_translation": 'Teacher health is a neglected topic.', "arabic_translation": 'صحة المعلم موضوع مهمل.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Digitalisierung des Unterrichts ist eine Herausforderung.', "english_translation": 'The digitalization of teaching is a challenge.', "arabic_translation": 'تحول التدريس رقميًا تحدي.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die Chancengleichheit im Bildungssystem muss verbessert werden.', "english_translation": 'Equal opportunities in the education system must be improved.', "arabic_translation": 'يجب تحسين الفرص المتكافئة في نظام التعليم.', "level": 'B2', "difficulty_score": 8, "category": 'Education'},
    {"german_text": 'Die lebenslange Bildung ist ein Menschenrecht.', "english_translation": 'Lifelong education is a human right.', "arabic_translation": 'التعليم مدى الحياة حق إنساني.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Bildungsforschung liefert wichtige Erkenntnisse.', "english_translation": 'Educational research provides important insights.', "arabic_translation": 'يوفر بحث التعليم رؤى مهمة.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die Reform des Hochschulsystems ist notwendig.', "english_translation": 'The reform of the higher education system is necessary.', "arabic_translation": 'إصلاح نظام التعليم العالي ضروري.', "level": 'B2', "difficulty_score": 7, "category": 'Education'},
    {"german_text": 'Die ontologische Frage nach dem Sein bleibt unbeantwortet.', "english_translation": 'The ontological question of being remains unanswered.', "arabic_translation": 'السؤال الأنطولوجي حول الوجود يبقى بلا إجابة.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der epistemologische Relativismus hinterfragt absolute Wahrheiten.', "english_translation": 'Epistemological relativism questions absolute truths.', "arabic_translation": 'تشكك النسبية المعرفية في الحقائق المطلقة.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die dialektische Methode führt zur Synthese widersprüchlicher Positionen.', "english_translation": 'The dialectical method leads to the synthesis of contradictory positions.', "arabic_translation": 'تؤدي الطريقة الجدلية إلى تركيب المواقع المتناقضة.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die metaphysische Debatte über den freien Willen ist ungelöst.', "english_translation": 'The metaphysical debate about free will is unresolved.', "arabic_translation": 'النقاش الميتافيزيقي حول الإرادة الحرة غير محلول.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Existentialismus betont die individuelle Verantwortung.', "english_translation": 'Existentialism emphasizes individual responsibility.', "arabic_translation": 'يؤكد الوجودية على المسؤولية الفردية.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die phänomenologische Betrachtung erfordert eine vorurteilsfreie Haltung.', "english_translation": 'Phenomenological observation requires an unbiased attitude.', "arabic_translation": 'يتطلب الملاحظة الظواهرية موقفًا خاليًا من التحيز.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der Utilitarismus bewertet Handlungen nach ihrem Nutzen.', "english_translation": 'Utilitarianism evaluates actions according to their utility.', "arabic_translation": 'تقيّم النفعية الأفعال وفقًا لفائدتها.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die hermeneutische Interpretation sucht nach tieferen Bedeutungsebenen.', "english_translation": 'Hermeneutic interpretation seeks deeper levels of meaning.', "arabic_translation": 'يبحث التفسير التأويلي عن مستويات أعمق من المعنى.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der Solipsismus stellt die Existenz anderer infrage.', "english_translation": 'Solipsism questions the existence of others.', "arabic_translation": 'تشكك الأنانية الذاتية في وجود الآخرين.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die transzendentale Argumentation untersucht die Bedingungen der Möglichkeit.', "english_translation": 'Transcendental argumentation examines the conditions of possibility.', "arabic_translation": 'تفحص الحجة التعالية شروط الإمكانية.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der Determinismus widerspricht dem Konzept des freien Willens.', "english_translation": 'Determinism contradicts the concept of free will.', "arabic_translation": 'يتناقض الحتمية مع مفهوم الإرادة الحرة.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die postmoderne Philosophie dekonstruiert etablierte Wahrheitsansprüche.', "english_translation": 'Postmodern philosophy deconstructs established claims to truth.', "arabic_translation": 'تفكك الفلسفة ما بعد الحداثة مزاعم الحقيقة الراسخة.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die stoische Haltung lehrt Gelassenheit angesichts des Unvermeidlichen.', "english_translation": 'The stoic attitude teaches calmness in the face of the inevitable.', "arabic_translation": 'تعلم الرواقية الهدوء في مواجهة المحتوم.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Pragmatismus misst Ideen an ihrer praktischen Anwendbarkeit.', "english_translation": 'Pragmatism measures ideas by their practical applicability.', "arabic_translation": 'تقيس البراغماتية الأفكار بقابليتها للتطبيق العملي.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die erkenntnistheoretische Skepsis zweifelt an der Zuverlässigkeit der Sinne.', "english_translation": 'Epistemological skepticism doubts the reliability of the senses.', "arabic_translation": 'تشكك الشكوكية المعرفية في موثوقية الحواس.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die ethische Diskussion um Autonomie und Fürsorge ist komplex.', "english_translation": 'The ethical discussion about autonomy and care is complex.', "arabic_translation": 'النقاش الأخلاقي حول الاستقلالية والرعاية معقد.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Nihilismus verneint jegliche objektive Bedeutung.', "english_translation": 'Nihilism denies any objective meaning.', "arabic_translation": 'تنفي العدمية أي معنى موضوعي.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Ästhetik erforscht die Natur des Schönen.', "english_translation": 'Aesthetics explores the nature of beauty.', "arabic_translation": 'يستكشف علم الجمال طبيعة الجمال.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Logik bietet Werkzeuge für schlüssiges Argumentieren.', "english_translation": 'Logic offers tools for sound reasoning.', "arabic_translation": 'يوفر المنطق أدوات للاستدلال السليم.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Philosophie des Geistes untersucht das Verhältnis von Körper und Bewusstsein.', "english_translation": 'Philosophy of mind examines the relationship between body and consciousness.', "arabic_translation": 'تفحص فلسفة العقل العلاقة بين الجسد والوعي.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der Kategorische Imperativ fordert universell gültige Maximen.', "english_translation": 'The categorical imperative demands universally valid maxims.', "arabic_translation": 'يطلب الأمر المطلق مقولات صالحة عالميًا.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Sozialphilosophie analysiert die Struktur menschlicher Gemeinschaften.', "english_translation": 'Social philosophy analyzes the structure of human communities.', "arabic_translation": 'تحلل الفلسفة الاجتماعية بنية المجتمعات البشرية.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Religionsphilosophie erörtert die Rationalität des Glaubens.', "english_translation": 'Philosophy of religion discusses the rationality of faith.', "arabic_translation": 'تناقش فلسفة الدين عقلانية الإيمان.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die politische Philosophie beschäftigt sich mit Gerechtigkeitsvorstellungen.', "english_translation": 'Political philosophy deals with concepts of justice.', "arabic_translation": 'تتعامل الفلسفة السياسية مع مفاهيم العدالة.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Sprachphilosophie hinterfragt die Beziehung zwischen Wort und Welt.', "english_translation": 'Philosophy of language questions the relationship between word and world.', "arabic_translation": 'تشكك فلسفة اللغة في العلاقة بين الكلمة والعالم.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der Konstruktivismus begreift Wissen als aktive Konstruktion.', "english_translation": 'Constructivism understands knowledge as active construction.', "arabic_translation": 'يفهم البنائية المعرفة كبناء نشط.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Anthropologie fragt nach der essentiellen Natur des Menschen.', "english_translation": 'Anthropology asks about the essential nature of humans.', "arabic_translation": 'تسأل الأنثروبولوجيا عن الطبيعة الجوهرية للإنسان.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Wertethik untersucht die Fundamente moralischer Urteile.', "english_translation": 'Value ethics examines the foundations of moral judgments.', "arabic_translation": 'تفحص أخلاقيات القيم أسس الأحكام الأخلاقية.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Falsifikationismus nach Popper ist ein Wissenschaftskriterium.', "english_translation": "Popper's falsificationism is a criterion of science.", "arabic_translation": 'التزييفية لبوبر هي معيار للعلم.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Vernunftkritik hinterfragt die Grenzen rationalen Denkens.', "english_translation": 'The critique of reason questions the limits of rational thinking.', "arabic_translation": 'تشكك نقد العقل في حدود التفكير العقلاني.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Diskurs über Identität und Differenz ist zentral für die moderne Philosophie.', "english_translation": 'The discourse on identity and difference is central to modern philosophy.', "arabic_translation": 'الخطاب حول الهوية والاختلاف مركزي للفلسفة الحديثة.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Phänomenologie des Leidens erfordert ein einfühlsames Verständnis.', "english_translation": 'The phenomenology of suffering requires empathetic understanding.', "arabic_translation": 'تتطلب ظواهرية المعاناة فهمًا متعاطفًا.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Rationalismus setzt auf die Kraft der Vernunft.', "english_translation": 'Rationalism relies on the power of reason.', "arabic_translation": 'تعتمد العقلانية على قوة العقل.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Kritik der instrumentellen Vernunft deckt Gefahren der Technokratie auf.', "english_translation": 'The critique of instrumental reason exposes the dangers of technocracy.', "arabic_translation": 'يكشف نقد العقل الآلي مخاطر التكنوقراطية.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Debatte über Universalismus und Partikularismus ist ungelöst.', "english_translation": 'The debate about universalism and particularism is unresolved.', "arabic_translation": 'النقاش حول العالمية والخصوصية غير محلول.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Philosophie der Geschichte sucht nach Sinn im historischen Prozess.', "english_translation": 'Philosophy of history seeks meaning in the historical process.', "arabic_translation": 'تبحث فلسفة التاريخ عن معنى في العملية التاريخية.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der Empirismus betont die Erfahrung als Quelle allen Wissens.', "english_translation": 'Empiricism emphasizes experience as the source of all knowledge.', "arabic_translation": 'تؤكد التجريبية على الخبرة كمصدر لكل المعرفة.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Bioethik befasst sich mit moralischen Fragen der Biowissenschaften.', "english_translation": 'Bioethics deals with moral questions of the life sciences.', "arabic_translation": 'تتعامل الأخلاقيات الحيوية مع أسئلة أخلاقية في علوم الحياة.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Dialektik von Herrschaft und Befreiung prägt die Gesellschaftstheorie.', "english_translation": 'The dialectic of domination and liberation shapes social theory.', "arabic_translation": 'تشكل جدلية الهيمنة والتحرر النظرية الاجتماعية.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Ontologie des digitalisierten Seins ist ein neues Forschungsfeld.', "english_translation": 'The ontology of digitized being is a new field of research.', "arabic_translation": 'أنطولوجيا الوجود الرقمي مجال بحث جديد.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der Diskursethik zufolge gelten Normen nur durch rationale Zustimmung.', "english_translation": 'According to discourse ethics, norms are valid only through rational consent.', "arabic_translation": 'وفقًا لأخلاقيات الخطاب، تكون المعايير صالحة فقط من خلال الموافقة العقلانية.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Auseinandersetzung mit dem Nichts ist ein zentrales Motiv der Existenzphilosophie.', "english_translation": 'Engagement with nothingness is a central motif of existential philosophy.', "arabic_translation": 'التعامل مع العدم هو دافع مركزي للفلسفة الوجودية.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Gerechtigkeitstheorie von Rawls basiert auf dem Gedankenexperiment des Urzustands.', "english_translation": "Rawls' theory of justice is based on the thought experiment of the original position.", "arabic_translation": 'تعتمد نظرية العدالة لرولس على تجربة التفكير للموقف الأصلي.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Der poststrukturalistische Ansatz dekonstruiert binäre Oppositionen.', "english_translation": 'The poststructuralist approach deconstructs binary oppositions.', "arabic_translation": 'يفكك النهج ما بعد البنيوي الثنائيات المعارضة.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die feministische Philosophie kritisiert patriarchale Denkmuster.', "english_translation": 'Feminist philosophy criticizes patriarchal thought patterns.', "arabic_translation": 'تنقد الفلسفة النسوية أنماط التفكير الأبوية.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Umweltethik fragt nach unserer Verantwortung gegenüber der Natur.', "english_translation": 'Environmental ethics asks about our responsibility towards nature.', "arabic_translation": 'تسأل الأخلاقيات البيئية عن مسؤوليتنا تجاه الطبيعة.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Tugendethik fokussiert auf den Charakter des handelnden Subjekts.', "english_translation": 'Virtue ethics focuses on the character of the acting subject.', "arabic_translation": 'تركز أخلاقيات الفضيلة على شخصية الفاعل.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Dekonstruktion nach Derrida hinterfragt die Metaphysik der Präsenz.', "english_translation": "Derrida's deconstruction questions the metaphysics of presence.", "arabic_translation": 'تشكك تفكيكية دريدا في ميتافيزيقا الحضور.', "level": 'C1', "difficulty_score": 10, "category": 'Philosophy'},
    {"german_text": 'Die Kritik der reinen Vernunft ist Kants Hauptwerk.', "english_translation": "The Critique of Pure Reason is Kant's main work.", "arabic_translation": 'نقد العقل الخالص هو العمل الرئيسي لكانط.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Der philosophische Diskurs über Bewusstsein und Artificial Intelligence ist aktuell.', "english_translation": 'The philosophical discourse about consciousness and artificial intelligence is current.', "arabic_translation": 'الخطاب الفلسفي حول الوعي والذكاء الاصطناعي راهني.', "level": 'C1', "difficulty_score": 9, "category": 'Philosophy'},
    {"german_text": 'Die Quantenverschränkung widerspricht klassischen Intuitionen.', "english_translation": 'Quantum entanglement contradicts classical intuitions.', "arabic_translation": 'التشابك الكمي يتعارض مع الحدوس الكلاسيكية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die epigenetische Forschung zeigt, dass Umwelteinflüsse die Genexpression verändern.', "english_translation": 'Epigenetic research shows that environmental influences change gene expression.', "arabic_translation": 'يظهر البحث اللاجيني أن التأثيرات البيئية تغير التعبير الجيني.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die CRISPR-Cas9-Technologie ermöglicht gezielte Genom-Editierung.', "english_translation": 'CRISPR-Cas9 technology enables targeted genome editing.', "arabic_translation": 'تمكن تقنية كريسبر-كاس9 من تعديل الجينوم المستهدف.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Stringtheorie versucht, alle fundamentalen Kräfte zu vereinen.', "english_translation": 'String theory attempts to unify all fundamental forces.', "arabic_translation": 'تحاول نظرية الأوتار توحيد جميع القوى الأساسية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Dunkle Materie macht etwa 27 Prozent des Universums aus.', "english_translation": 'Dark matter makes up about 27 percent of the universe.', "arabic_translation": 'تشكل المادة المظلمة حوالي 27 بالمائة من الكون.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Neuroplastizität beweist die Anpassungsfähigkeit des Gehirns.', "english_translation": "Neuroplasticity proves the brain's adaptability.", "arabic_translation": 'يثبت المرونة العصبية قدرة الدماغ على التكيف.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Supraleitung ermöglicht verlustfreien Stromtransport.', "english_translation": 'Superconductivity enables lossless power transmission.', "arabic_translation": 'تمكّن الموصلية الفائقة من نقل الكهرباء بدون فقد.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Künstliche Intelligenz revolutioniert die Mustererkennung.', "english_translation": 'Artificial intelligence revolutionizes pattern recognition.', "arabic_translation": 'يُحدث الذكاء الاصطناعي ثورة في التعرف على الأنماط.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Quantencomputer nutzen Superposition für parallele Berechnungen.', "english_translation": 'Quantum computers use superposition for parallel computations.', "arabic_translation": 'تستخدم الحواسيب الكمومية التراكب للحسابات المتوازية.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Proteinfaltung ist ein ungelöstes Problem der Biochemie.', "english_translation": 'Protein folding is an unsolved problem in biochemistry.', "arabic_translation": 'طي البروتين مشكلة غير محلولة في الكيمياء الحيوية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Evolutionstheorie erklärt die Diversität des Lebens.', "english_translation": 'The theory of evolution explains the diversity of life.', "arabic_translation": 'تشرح نظرية التطور تنوع الحياة.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Schwarzen Löcher sind Regionen extremer Gravitation.', "english_translation": 'Black holes are regions of extreme gravity.', "arabic_translation": 'الثقوب السوداء مناطق ذات جاذبية شديدة.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Blockchain-Technologie dezentralisiert Datenspeicherung.', "english_translation": 'Blockchain technology decentralizes data storage.', "arabic_translation": 'تُلامركزية تقنية بلوكتشين تخزين البيانات.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Thermodynamik zweiter Ordnung beschreibt irreversible Prozesse.', "english_translation": 'Second-order thermodynamics describes irreversible processes.', "arabic_translation": 'يصف الديناميكا الحرارية من الدرجة الثانية العمليات غير القابلة للعكس.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Mikrobiom-Forschung enthüllt komplexe Ökosysteme im Körper.', "english_translation": 'Microbiome research reveals complex ecosystems in the body.', "arabic_translation": 'يكشف بحث الميكروبيوم أنظمة بيئية معقدة في الجسم.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Gravitationswellen bestätigen Einsteins Vorhersagen.', "english_translation": "Gravitational waves confirm Einstein's predictions.", "arabic_translation": 'تؤكد الموجات الثقالية تنبؤات أينشتاين.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Stammzelltherapie bietet Potenzial für regenerative Medizin.', "english_translation": 'Stem cell therapy offers potential for regenerative medicine.', "arabic_translation": 'يوفر علاج الخلايا الجذعية إمكانات للطب التجديدي.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Photosynthese ist ein hochkomplexer biochemischer Prozess.', "english_translation": 'Photosynthesis is a highly complex biochemical process.', "arabic_translation": 'التمثيل الضوئي عملية كيميائية حيوية معقدة للغاية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Quantenchromodynamik beschreibt die starke Wechselwirkung.', "english_translation": 'Quantum chromodynamics describes the strong interaction.', "arabic_translation": 'يصف كروموديناميكا الكم التفاعل القوي.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Bioinformatik kombiniert Biologie mit algorithmischer Analyse.', "english_translation": 'Bioinformatics combines biology with algorithmic analysis.', "arabic_translation": 'يجمع المعلومات الأحيائية بين الأحياء والتحليل الخوارزمي.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Kosmologie erforscht die Entstehung und Entwicklung des Universums.', "english_translation": 'Cosmology explores the origin and evolution of the universe.', "arabic_translation": 'تستكشف علم الكونيات نشأة وتطور الكون.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Systembiologie betrachtet Organismen als Ganzes.', "english_translation": 'Systems biology views organisms as wholes.', "arabic_translation": 'ينظر علم الأحياء النظمي إلى الكائنات الحية ككل.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Nanorobotik könnte medizinische Anwendungen revolutionieren.', "english_translation": 'Nanorobotics could revolutionize medical applications.', "arabic_translation": 'يمكن للنانوروبوتات أن تُحدث ثورة في التطبيقات الطبية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Plasmaphysik untersucht den vierten Aggregatzustand.', "english_translation": 'Plasma physics investigates the fourth state of matter.', "arabic_translation": 'يدرس فيزياء البلازما حالة المادة الرابعة.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Synthetische Biologie konstruiert neue biologische Systeme.', "english_translation": 'Synthetic biology constructs new biological systems.', "arabic_translation": 'يبني علم الأحياء الاصطناعي أنظمة بيولوجية جديدة.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Relativitätstheorie verändert unser Verständnis von Raum und Zeit.', "english_translation": 'The theory of relativity changes our understanding of space and time.', "arabic_translation": 'تغير نظرية النسبية فهمنا للزمكان.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Metagenomik analysiert genetisches Material aus Umweltproben.', "english_translation": 'Metagenomics analyzes genetic material from environmental samples.', "arabic_translation": 'تحلل الميتاجينوميكس المادة الجينية من العينات البيئية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Quantenkryptographie bietet theoretisch unhackbare Kommunikation.', "english_translation": 'Quantum cryptography offers theoretically unhackable communication.', "arabic_translation": 'توفر التشفير الكمي اتصالات غير قابلة للاختراق نظريًا.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Exoplaneten-Forschung sucht nach bewohnbaren Welten.', "english_translation": 'Exoplanet research searches for habitable worlds.', "arabic_translation": 'يبحث بحث الكواكب الخارجية عن عوالم صالحة للسكن.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Kristallographie bestimmt die atomare Struktur von Materialien.', "english_translation": 'Crystallography determines the atomic structure of materials.', "arabic_translation": 'يحدد علم البلورات البنية الذرية للمواد.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Ökotoxikologie untersucht die Auswirkungen von Schadstoffen auf Ökosysteme.', "english_translation": 'Ecotoxicology examines the effects of pollutants on ecosystems.', "arabic_translation": 'يدرس علم السموم البيئية تأثير الملوثات على النظم البيئية.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Higgs-Teilchen-Entdeckung bestätigte das Standardmodell.', "english_translation": 'The Higgs particle discovery confirmed the Standard Model.', "arabic_translation": 'أكد اكتشاف جسيم هيغز النموذج القياسي.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Fluiddynamik modelliert Strömungsverhalten.', "english_translation": 'Fluid dynamics models flow behavior.', "arabic_translation": 'ينمذج ديناميكا الموائع سلوك التدفق.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Elektrophysiologie erforscht elektrische Signale in Zellen.', "english_translation": 'Electrophysiology explores electrical signals in cells.', "arabic_translation": 'يستكشف الفيزيولوجيا الكهربائية الإشارات الكهربائية في الخلايا.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Strömungsmechanik ist grundlegend für die Aerodynamik.', "english_translation": 'Fluid mechanics is fundamental to aerodynamics.', "arabic_translation": 'ميكانيكا الموائع أساسية للديناميكا الهوائية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Geoinformatik verbindet Geographie mit Datenanalyse.', "english_translation": 'Geoinformatics combines geography with data analysis.', "arabic_translation": 'يجمع المعلومات الجغرافية بين الجغرافيا وتحليل البيانات.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die molekulare Pathologie identifiziert Krankheitsmechanismen.', "english_translation": 'Molecular pathology identifies disease mechanisms.', "arabic_translation": 'يحدد علم الأمراض الجزيئي آليات المرض.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Astrophysik erforscht die physikalischen Prozesse im Kosmos.', "english_translation": 'Astrophysics explores physical processes in the cosmos.', "arabic_translation": 'يستكشف الفيزياء الفلكية العمليات الفيزيائية في الكون.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die algorithmische Komplexitätstheorie klassifiziert Rechenprobleme.', "english_translation": 'Algorithmic complexity theory classifies computational problems.', "arabic_translation": 'تصنف نظرية التعقيد الخوارزمي مشاكل الحساب.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Photovoltaik wandelt Sonnenlicht direkt in Elektrizität um.', "english_translation": 'Photovoltaics converts sunlight directly into electricity.', "arabic_translation": 'تحول الخلايا الكهروضوئية ضوء الشمس مباشرة إلى كهرباء.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Biomechanik analysiert Bewegung und Kräfte in Lebewesen.', "english_translation": 'Biomechanics analyzes movement and forces in living organisms.', "arabic_translation": 'تحلل الميكانيكا الحيوية الحركة والقوى في الكائنات الحية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Radioastronomie beobachtet den Kosmos im Radiowellenbereich.', "english_translation": 'Radio astronomy observes the cosmos in the radio wave range.', "arabic_translation": 'يرصد علم الفلك الراديوي الكون في نطاق موجات الراديو.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Materialwissenschaft entwickelt Werkstoffe mit maßgeschneiderten Eigenschaften.', "english_translation": 'Materials science develops materials with tailored properties.', "arabic_translation": 'يطور علم المواد مواد ذات خصائص مصممة خصيصًا.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Kognitive Neurowissenschaft untersucht die neuronalen Grundlagen des Denkens.', "english_translation": 'Cognitive neuroscience examines the neural basis of thinking.', "arabic_translation": 'يدرس علم الأعصاب المعرفي الأسس العصبية للتفكير.', "level": 'C1', "difficulty_score": 10, "category": 'Science'},
    {"german_text": 'Die Geothermie nutzt die Wärmeenergie aus dem Erdinneren.', "english_translation": "Geothermal energy uses heat energy from the earth's interior.", "arabic_translation": 'تستخدم الطاقة الحرارية الأرضية طاقة الحرارة من باطن الأرض.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Spektralanalyse ermöglicht die Bestimmung chemischer Zusammensetzungen.', "english_translation": 'Spectral analysis enables the determination of chemical compositions.', "arabic_translation": 'يتيح التحليل الطيفي تحديد التراكيب الكيميائية.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Cybernetik beschäftigt sich mit Regelungs- und Kommunikationsprozessen.', "english_translation": 'Cybernetics deals with control and communication processes.', "arabic_translation": 'يتعامل علم السيبرنيطيقا مع عمليات التحكم والاتصال.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Fusionstechnologie verspricht nahezu unbegrenzte Energie.', "english_translation": 'Fusion technology promises virtually unlimited energy.', "arabic_translation": 'تعد تقنية الاندماج بطاقة شبه غير محدودة.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Computertomographie erzeugt dreidimensionale Schnittbilder.', "english_translation": 'Computed tomography generates three-dimensional cross-sectional images.', "arabic_translation": 'ينتج التصوير المقطعي المحوسب صورًا مقطعية ثلاثية الأبعاد.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die Ökologische Modellierung simuliert komplexe Umweltzusammenhänge.', "english_translation": 'Ecological modeling simulates complex environmental relationships.', "arabic_translation": 'يحاكي النمذجة البيئية العلاقات البيئية المعقدة.', "level": 'C1', "difficulty_score": 9, "category": 'Science'},
    {"german_text": 'Die makroökonomische Theorie erklärt gesamtwirtschaftliche Zusammenhänge.', "english_translation": 'Macroeconomic theory explains economy-wide relationships.', "arabic_translation": 'تشرح النظرية الاقتصادية الكلية العلاقات على مستوى الاقتصاد.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Geldpolitik der EZB beeinflusst die Zinsniveaus im Euroraum.', "english_translation": "The ECB's monetary policy influences interest rate levels in the eurozone.", "arabic_translation": 'تؤثر السياسة النقدية للبنك المركزي الأوروبي على مستويات الفائدة في منطقة اليورو.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Phillips-Kurve beschreibt den Zusammenhang zwischen Inflation und Arbeitslosigkeit.', "english_translation": 'The Phillips curve describes the relationship between inflation and unemployment.', "arabic_translation": 'يصف منحنى فيليبس العلاقة بين التضخم والبطالة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Spieltheorie modelliert strategische Entscheidungsfindung.', "english_translation": 'Game theory models strategic decision-making.', "arabic_translation": 'تنمذج نظرية الألعاب اتخاذ القرارات الاستراتيجية.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die keynesianische Fiskalpolitik befürwortet staatliche Intervention.', "english_translation": 'Keynesian fiscal policy advocates state intervention.', "arabic_translation": 'تدعو السياسة المالية الكينزية إلى تدخل الدولة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Verhaltensökonomik analysiert psychologische Faktoren in wirtschaftlichen Entscheidungen.', "english_translation": 'Behavioral economics analyzes psychological factors in economic decisions.', "arabic_translation": 'تحلل الاقتصاد السلوكي العوامل النفسية في القرارات الاقتصادية.', "level": 'C1', "difficulty_score": 10, "category": 'Economics'},
    {"german_text": 'Die Arbitrage-Möglichkeit nutzt Preisunterschiede zwischen Märkten.', "english_translation": 'The arbitrage opportunity exploits price differences between markets.', "arabic_translation": 'تستغل فرصة المراجحة فروق الأسعار بين الأسواق.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Portfoliotheorie von Markowitz optimiert Risiko und Rendite.', "english_translation": "Markowitz's portfolio theory optimizes risk and return.", "arabic_translation": 'تحسن نظرية المحفظة لماركويتز المخاطرة والعائد.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Konjunkturzyklen durchlaufen verschiedene Phasen.', "english_translation": 'Business cycles go through various phases.', "arabic_translation": 'تمر الدورات الاقتصادية بمراحل مختلفة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Kapitalwertmethode bewertet Investitionsprojekte.', "english_translation": 'The net present value method evaluates investment projects.', "arabic_translation": 'تقيّم طريقة القيمة الحالية الصافية مشاريع الاستثمار.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Liquiditätspräferenztheorie erklärt die Zinsbildung.', "english_translation": 'The liquidity preference theory explains interest rate formation.', "arabic_translation": 'تشرح نظرية تفضيل السيولة تكوين أسعار الفائدة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Optionspreistheorie nach Black-Scholes revolutionierte den Finanzmarkt.', "english_translation": 'The Black-Scholes option pricing theory revolutionized the financial market.', "arabic_translation": 'أحدثت نظرية تسعير الخيارات لبلاك-شولز ثورة في السوق المالي.', "level": 'C1', "difficulty_score": 10, "category": 'Economics'},
    {"german_text": 'Die Wertschöpfungskette analysiert alle Stufen der Produktion.', "english_translation": 'The value chain analyzes all stages of production.', "arabic_translation": 'تحلل سلسلة القيمة جميع مراحل الإنتاج.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Angebots- und Nachfragekurve bestimmt den Gleichgewichtspreis.', "english_translation": 'The supply and demand curve determines the equilibrium price.', "arabic_translation": 'يحدد منحنى العرض والطلب سعر التوازن.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die fiskalische Multiplikatorwirkung verstärkt staatliche Ausgaben.', "english_translation": 'The fiscal multiplier effect amplifies government spending.', "arabic_translation": 'يعزز تأثير المضاعف المالي الإنفاق الحكومي.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Transaktionskostenökonomik erklärt die Existenz von Unternehmen.', "english_translation": 'Transaction cost economics explains the existence of firms.', "arabic_translation": 'يشرح اقتصاديات تكلفة المعاملات وجود الشركات.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Devisenmarktintervention stabilisiert Wechselkurse.', "english_translation": 'Foreign exchange market intervention stabilizes exchange rates.', "arabic_translation": 'يستهدف تدخل سوق الصرف استقرار أسعار الصرف.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Crowdfunding-Plattformen demokratisieren die Kapitalbeschaffung.', "english_translation": 'Crowdfunding platforms democratize capital raising.', "arabic_translation": 'تُديمقراطية منصات التمويل الجماعي جمع رأس المال.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die quantitative Lockerung erhöht die Geldmenge.', "english_translation": 'Quantitative easing increases the money supply.', "arabic_translation": 'يزيد التسهيل الكمي المعروض النقدي.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Wettbewerbsverzerrung beeinträchtigt den freien Markt.', "english_translation": 'Competition distortion impairs the free market.', "arabic_translation": 'يُضعف تشويه المنافسة السوق الحرة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Schattenwirtschaft entzieht sich der staatlichen Kontrolle.', "english_translation": 'The shadow economy evades state control.', "arabic_translation": 'يتهرب الاقتصاد الخفي من سيطرة الدولة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Strukturpolitik fördert langfristiges Wirtschaftswachstum.', "english_translation": 'Structural policy promotes long-term economic growth.', "arabic_translation": 'تعزز السياسة الهيكلية النمو الاقتصادي طويل المدى.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Handelsliberalisierung reduziert Zölle und Handelshemmnisse.', "english_translation": 'Trade liberalization reduces tariffs and trade barriers.', "arabic_translation": 'يُقلل تحرير التجارة الرسوم الجمركية والحواجز التجارية.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Venture-Capital-Finanzierung unterstützt innovative Start-ups.', "english_translation": 'Venture capital financing supports innovative start-ups.', "arabic_translation": 'يدعم تمويل رأس المال الاستثماري الشركات الناشئة المبتكرة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Rezession wird durch zwei aufeinanderfolgende Quartale negativen Wachstums definiert.', "english_translation": 'Recession is defined by two consecutive quarters of negative growth.', "arabic_translation": 'يُعرّف الركود بربعين متتاليين من النمو السلبي.', "level": 'C1', "difficulty_score": 10, "category": 'Economics'},
    {"german_text": 'Die Kapitalflussrechnung dokumentiert Zahlungsströme.', "english_translation": 'The cash flow statement documents payment flows.', "arabic_translation": 'تُوثق قائمة التدفقات النقدية تدفقات المدفوعات.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Marktvolatilität misst die Schwankungsintensität von Preisen.', "english_translation": 'Market volatility measures the intensity of price fluctuations.', "arabic_translation": 'يقيس تقلب السوق شدة تقلبات الأسعار.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Fiskalunion vertieft die wirtschaftliche Integration.', "english_translation": 'Fiscal union deepens economic integration.', "arabic_translation": 'يُعمق الاتحاد المالي التكامل الاقتصادي.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Leverage-Ratio begrenzt die Verschuldung von Banken.', "english_translation": 'The leverage ratio limits bank indebtedness.', "arabic_translation": 'يحدّ نسبة الرافعة المالية من مديونية البنوك.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Konsumfunktion beschreibt das Verhältnis von Einkommen und Ausgaben.', "english_translation": 'The consumption function describes the relationship between income and spending.', "arabic_translation": 'تصف دالة الاستهلاك العلاقة بين الدخل والإنفاق.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Deflation führt zu fallenden Preisen und Wirtschaftsschwäche.', "english_translation": 'Deflation leads to falling prices and economic weakness.', "arabic_translation": 'يؤدي الانكماش إلى انخفاض الأسعار وضعف الاقتصاد.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Stagflation kombiniert hohe Inflation mit Arbeitslosigkeit.', "english_translation": 'Stagflation combines high inflation with unemployment.', "arabic_translation": 'يجمع الركود التضخمي بين التضخم المرتفع والبطالة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Hedge-Fonds nutzen komplexe Strategien zur Renditeoptimierung.', "english_translation": 'Hedge funds use complex strategies for return optimization.', "arabic_translation": 'تستخدم صناديج التحوط استراتيجيات معقدة لتحسين العائد.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Anleihenrendite spiegelt das Risiko des Emittenten wider.', "english_translation": "Bond yield reflects the issuer's risk.", "arabic_translation": 'يعكس عائد السندات مخاطر المُصدر.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Privatisierung überträgt staatliche Aufgaben an private Unternehmen.', "english_translation": 'Privatization transfers state tasks to private companies.', "arabic_translation": 'ينقل الخصخصة المهام الحكومية إلى شركات خاصة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Komparativen Kostenvorteile begründen internationalen Handel.', "english_translation": 'Comparative cost advantages justify international trade.', "arabic_translation": 'تبرر مزايا التكلفة النسبية التجارة الدولية.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Zentralbilanzpolitik beeinflusst die gesamtwirtschaftliche Nachfrage.', "english_translation": 'Central balance sheet policy influences aggregate demand.', "arabic_translation": 'تؤثر سياسة الميزانية المركزية على الطلب الكلي.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Insolvenzordnung regelt das Verfahren bei Zahlungsunfähigkeit.', "english_translation": 'The insolvency code regulates the procedure in case of insolvency.', "arabic_translation": 'ينظم قانون الإفلاس الإجراءات في حالة العجز عن السداد.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Kreditwürdigkeitsprüfung bewertet die Bonität von Schuldnern.', "english_translation": 'Creditworthiness assessment evaluates the creditworthiness of debtors.', "arabic_translation": 'يُقيّم تقييم الجدارة الائتمانية أهلية المدينين.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Kapitalmarkteffizienzhypothese besagt, dass Preise alle Informationen reflektieren.', "english_translation": 'The efficient market hypothesis states that prices reflect all information.', "arabic_translation": 'تنص فرضية كفاءة السوق على أن الأسعار تعكس جميع المعلومات.', "level": 'C1', "difficulty_score": 10, "category": 'Economics'},
    {"german_text": 'Die Wertschöpfung bemisst den wirtschaftlichen Mehrwert.', "english_translation": 'Value added measures economic value added.', "arabic_translation": 'يقيس القيمة المضافة القيمة الاقتصادية المضافة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Transferleistungen redistribuieren Einkommen.', "english_translation": 'Transfer payments redistribute income.', "arabic_translation": 'تُعيد مدفوعات التحويل توزيع الدخل.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Abschreibung berücksichtigt den Wertverlust von Vermögensgegenständen.', "english_translation": 'Depreciation accounts for the loss of value of assets.', "arabic_translation": 'يأخذ الاستهلاك في الاعتبار انخفاض قيمة الأصول.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Börsenregulierung schützt Anleger vor Betrug.', "english_translation": 'Stock market regulation protects investors from fraud.', "arabic_translation": 'يحمي تنظيم سوق المستثمرين من الاحتيال.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Wirtschaftsforschung prognostiziert makroökonomische Entwicklungen.', "english_translation": 'Economic research forecasts macroeconomic developments.', "arabic_translation": 'يتنبأ البحث الاقتصادي بالتطورات الاقتصادية الكلية.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Derivate ermöglichen die Absicherung gegen Risiken.', "english_translation": 'Derivatives enable hedging against risks.', "arabic_translation": 'تمكن المشتقات من التحوط ضد المخاطر.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Konjunkturprognose verwendet ökonometrische Modelle.', "english_translation": 'Economic forecasting uses econometric models.', "arabic_translation": 'يستخدم التنبؤ الاقتصادي نماذج اقتصادية قياسية.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Liquiditätsreserve sichert die Zahlungsfähigkeit.', "english_translation": 'The liquidity reserve ensures solvency.', "arabic_translation": 'يضمن الاحتياطي النقدي السيولة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Kapitalallokation bestimmt die Verteilung von Ressourcen.', "english_translation": 'Capital allocation determines the distribution of resources.', "arabic_translation": 'يحدد تخصيص رأس المال توزيع الموارد.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Bilanzanalyse offenbart die finanzielle Gesundheit eines Unternehmens.', "english_translation": 'Balance sheet analysis reveals the financial health of a company.', "arabic_translation": 'يكشف تحليل الميزانية الصحة المالية للشركة.', "level": 'C1', "difficulty_score": 9, "category": 'Economics'},
    {"german_text": 'Die Dekarbonisierung der Wirtschaft erfordert massive Investitionen.', "english_translation": 'Decarbonization of the economy requires massive investments.', "arabic_translation": 'يتطلب إزالة الكربون من الاقتصاد استثمارات ضخمة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Biodiversitätskrise bedroht die Stabilität von Ökosystemen.', "english_translation": 'The biodiversity crisis threatens the stability of ecosystems.', "arabic_translation": 'تهدد أزمة التنوع البيولوجي استقرار النظم البيئية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Kreislaufwirtschaft minimiert Abfall durch Wiederverwertung.', "english_translation": 'The circular economy minimizes waste through recycling.', "arabic_translation": 'يُقلل الاقتصاد الدائري النفايات من خلال إعادة التدوير.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Versauerung der Ozeane gefährdet marine Lebensräume.', "english_translation": 'Ocean acidification endangers marine habitats.', "arabic_translation": 'يهدد تحمض المحيطات الموائل البحرية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die nachhaltige Landwirtschaft reduziert den Einsatz von Pestiziden.', "english_translation": 'Sustainable agriculture reduces the use of pesticides.', "arabic_translation": 'يُقلل الزراعة المستدامة استخدام المبيدات.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Treibhausgasemissionen müssen drastisch gesenkt werden.', "english_translation": 'Greenhouse gas emissions must be drastically reduced.', "arabic_translation": 'يجب خفض انبعاثات الغازات الدفيئة بشكل جذري.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die ökologische Fußabdruck-Analyse quantifiziert Ressourcenverbrauch.', "english_translation": 'The ecological footprint analysis quantifies resource consumption.', "arabic_translation": 'تقيّم تحليل البصمة البيئية استهلاك الموارد.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Permafrost-Schmelze setzt Methan frei.', "english_translation": 'Permafrost thawing releases methane.', "arabic_translation": 'يُطلق ذوبان الجليد الدائم الميثان.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Carbon-Capture-Technologie bindet CO2 aus der Atmosphäre.', "english_translation": 'Carbon capture technology binds CO2 from the atmosphere.', "arabic_translation": 'ترتبط تقنية احتجاز الكربون بثاني أكسيد الكربون من الغلاف الجوي.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Desertifikation schreitet in vielen Regionen fort.', "english_translation": 'Desertification progresses in many regions.', "arabic_translation": 'يتقدم التصحر في العديد من المناطق.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Wasserknappheit wird zu einem globalen Problem.', "english_translation": 'Water scarcity is becoming a global problem.', "arabic_translation": 'يُصبح نقص المياه مشكلة عالمية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die erneuerbaren Energien sollen fossile Brennstoffe ersetzen.', "english_translation": 'Renewable energies are to replace fossil fuels.', "arabic_translation": 'يجب أن تحل الطاقات المتجددة محل الوقود الأحفوري.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Entwaldung im Amazonasgebiet hat dramatische Folgen.', "english_translation": 'Deforestation in the Amazon region has dramatic consequences.', "arabic_translation": 'لإزالة الغابات في منطقة الأمازون عواقب دراماتيكية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Umweltverträglichkeitsprüfung bewertet Projekte vor der Genehmigung.', "english_translation": 'The environmental impact assessment evaluates projects before approval.', "arabic_translation": 'يُقيّم تقييم الأثر البيئي المشاريع قبل الموافقة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Mikroplastik-Verschmutzung betrifft alle marinen Ökosysteme.', "english_translation": 'Microplastic pollution affects all marine ecosystems.', "arabic_translation": 'يؤثر تلوث اللدائن الدقيقة على جميع النظم البيئية البحرية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Klimaresilienz beschreibt die Anpassungsfähigkeit an Klimaveränderungen.', "english_translation": 'Climate resilience describes the ability to adapt to climate change.', "arabic_translation": 'يصف المرونة المناخية القدرة على التكيف مع تغير المناخ.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Artensterben-Rate hat sich dramatisch beschleunigt.', "english_translation": 'The species extinction rate has accelerated dramatically.', "arabic_translation": 'تسارع معدل انقراض الأنواع بشكل دراماتيكي.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Ökobilanzierung quantifiziert Umweltauswirkungen über den Lebenszyklus.', "english_translation": 'Life cycle assessment quantifies environmental impacts over the lifecycle.', "arabic_translation": 'تُقيّم تقييم دورة الحياة التأثيرات البيئية خلال دورة الحياة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Energiewende erfordert den Umbau der Infrastruktur.', "english_translation": 'The energy transition requires restructuring the infrastructure.', "arabic_translation": 'يتطلب تحول الطاقة إعادة بناء البنية التحتية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Umweltgerechtigkeit thematisiert ungleiche Belastungen.', "english_translation": 'Environmental justice addresses unequal burdens.', "arabic_translation": 'يتناول العدالة البيئية الأعباء غير المتكافئة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Aufforstung bindet Kohlendioxid und schützt die Biodiversität.', "english_translation": 'Reforestation binds carbon dioxide and protects biodiversity.', "arabic_translation": 'ترتبط إعادة التشجير بثاني أكسيد الكربون وتحمي التنوع البيولوجي.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Bodendegradation gefährdet die Nahrungsmittelproduktion.', "english_translation": 'Soil degradation threatens food production.', "arabic_translation": 'يهدد تدهور التربة إنتاج الغذاء.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Nachhaltigkeitsziele der UN setzen globale Rahmenbedingungen.', "english_translation": "The UN's sustainability goals set global frameworks.", "arabic_translation": 'تضع أهداف الاستدامة للأمم المتحدة أطرًا عالمية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Klimaanpassungsstrategien variieren je nach Region.', "english_translation": 'Climate adaptation strategies vary by region.', "arabic_translation": 'تختلف استراتيجيات التكيف المناخي حسب المنطقة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die grüne Wasserstofftechnologie gilt als Schlüssel zur Dekarbonisierung.', "english_translation": 'Green hydrogen technology is considered key to decarbonization.', "arabic_translation": 'تُعتبر تكنولوجيا الهيدروجين الأخضر مفتاحًا لإزالة الكربون.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Meeresströmungen beeinflussen das globale Klima.', "english_translation": 'Ocean currents influence the global climate.', "arabic_translation": 'تؤثر تيارات المحيط على المناخ العالمي.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Luftqualitätsstandards schützen die öffentliche Gesundheit.', "english_translation": 'Air quality standards protect public health.', "arabic_translation": 'تحمي معايير جودة الهواء الصحة العامة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Überfischung bedroht die Bestände vieler Fischarten.', "english_translation": 'Overfishing threatens the stocks of many fish species.', "arabic_translation": 'يهدد الصيد الجائر مخزون العديد من أنواع الأسماك.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Umweltbildung fördert ökologisches Bewusstsein.', "english_translation": 'Environmental education promotes ecological awareness.', "arabic_translation": 'يعزز التعليم البيئي الوعي البيئي.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Klimaflüchtlinge sind eine wachsende Bevölkerungsgruppe.', "english_translation": 'Climate refugees are a growing population group.', "arabic_translation": 'لاجئو المناخ مجموعة سكانية متنامية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Abfallhierarchie priorisiert Vermeidung vor Entsorgung.', "english_translation": 'The waste hierarchy prioritizes prevention over disposal.', "arabic_translation": 'يُرتب هرم النفايات الأولوية للوقاية على التخلص.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Emissionszertifikate schaffen einen Markt für CO2-Reduktion.', "english_translation": 'Emission certificates create a market for CO2 reduction.', "arabic_translation": 'تُحدث شهادات الانبعاثات سوقًا لخفض ثاني أكسيد الكربون.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die ökologische Landwirtschaft verzichtet auf synthetische Düngemittel.', "english_translation": 'Organic farming refrains from synthetic fertilizers.', "arabic_translation": 'تمتنع الزراعة العضوية عن الأسمدة الاصطناعية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Grundwasserbelastung durch Nitrat ist ein ernstes Problem.', "english_translation": 'Groundwater contamination by nitrate is a serious problem.', "arabic_translation": 'تلوث المياه الجوفية بالنترات مشكلة خطيرة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Klimaprojektionen basieren auf komplexen Simulationsmodellen.', "english_translation": 'Climate projections are based on complex simulation models.', "arabic_translation": 'تعتمد التوقعات المناخية على نماذج محاكاة معقدة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Renaturierung von Mooren bindet große Mengen CO2.', "english_translation": 'Rewetting of bogs binds large amounts of CO2.', "arabic_translation": 'ترتبط إعادة تأهيل المستنقعات بكميات كبيرة من ثاني أكسيد الكربون.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Umweltökonomie internalisiert externe Kosten.', "english_translation": 'Environmental economics internalizes external costs.', "arabic_translation": 'يُداخل الاقتصاد البيئي التكاليف الخارجية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Korallenbleiche ist ein Indikator für die Ozeanerwärmung.', "english_translation": 'Coral bleaching is an indicator of ocean warming.', "arabic_translation": 'ابيضاض المرجان مؤشر على احترار المحيطات.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Nachhaltigkeitstransformation erfordert gesellschaftlichen Wandel.', "english_translation": 'The sustainability transformation requires societal change.', "arabic_translation": 'يتطلب تحول الاستدامة تغييرًا مجتمعيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die grüne Infrastruktur kombiniert ökologische und städtebauliche Planung.', "english_translation": 'Green infrastructure combines ecological and urban planning.', "arabic_translation": 'يجمع البنية التحتية الخضراء بين التخطيط البيئي والعمراني.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Wasseraufbereitungstechnologie ermöglicht die Wiederverwendung.', "english_translation": 'Water purification technology enables reuse.', "arabic_translation": 'تتيح تكنولوجيا تنقية المياه إعادة الاستخدام.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Umweltzerstörung hat irreversible Folgen.', "english_translation": 'Environmental destruction has irreversible consequences.', "arabic_translation": 'للتدمير البيئي عواقب لا رجعة فيها.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Bioökonomie nutzt biologische Ressourcen nachhaltig.', "english_translation": 'The bioeconomy uses biological resources sustainably.', "arabic_translation": 'يستخدم الاقتصاد الحيوي الموارد البيولوجية بشكل مستدام.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Kipppunkte im Klimasystem könnten unumkehrbare Veränderungen auslösen.', "english_translation": 'Tipping points in the climate system could trigger irreversible changes.', "arabic_translation": 'قد تُطلق نقاط التحول في النظام المناخي تغييرات لا رجعة فيها.', "level": 'C1', "difficulty_score": 10, "category": 'Environment'},
    {"german_text": 'Die Ressourcenknappheit führt zu geopolitischen Spannungen.', "english_translation": 'Resource scarcity leads to geopolitical tensions.', "arabic_translation": 'يؤدي ندرة الموارد إلى توترات جيوسياسية.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die nachhaltige Stadtplanung integriert Grünflächen und Verkehrskonzepte.', "english_translation": 'Sustainable urban planning integrates green spaces and transportation concepts.', "arabic_translation": 'يدمج التخطيط الحضري المستدام المساحات الخضراء ومفاهيم النقل.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Umweltverschmutzung durch Schwermetalle hat langfristige Auswirkungen.', "english_translation": 'Heavy metal pollution has long-term effects.', "arabic_translation": 'لتلوث المعادن الثقيلة تأثيرات طويلة المدى.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Klimagerechtigkeit fordert faire Lastenverteilung.', "english_translation": 'Climate justice demands fair distribution of burdens.', "arabic_translation": 'تطالب العدالة المناخية بتوزيع عادل للأعباء.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die Ökosystemdienstleistungen sind für das menschliche Wohlergehen unverzichtbar.', "english_translation": 'Ecosystem services are indispensable for human well-being.', "arabic_translation": 'خدمات النظم البيئية لا غنى عنها لرفاهية الإنسان.', "level": 'C1', "difficulty_score": 10, "category": 'Environment'},
    {"german_text": 'Die Anpassung an den Klimawandel erfordert innovative Lösungen.', "english_translation": 'Adaptation to climate change requires innovative solutions.', "arabic_translation": 'يتطلب التكيف مع تغير المناخ حلولًا مبتكرة.', "level": 'C1', "difficulty_score": 9, "category": 'Environment'},
    {"german_text": 'Die literarische Moderne bricht mit traditionellen Erzählstrukturen.', "english_translation": 'Literary modernism breaks with traditional narrative structures.', "arabic_translation": 'تكسر الحداثة الأدبية مع هياكل السرد التقليدية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die expressionistische Bewegung suchte nach emotionaler Wahrheit.', "english_translation": 'The expressionist movement sought emotional truth.', "arabic_translation": 'سعت الحركة التعبيرية إلى الحقيقة العاطفية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die postkoloniale Literatur dekonstruiert imperiale Narrative.', "english_translation": 'Postcolonial literature deconstructs imperial narratives.', "arabic_translation": 'تُفكك الأدب ما بعد الاستعمار السرد الإمبراطوري.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Aufklärung propagierte die Emanzipation durch Vernunft.', "english_translation": 'The Enlightenment promoted emancipation through reason.', "arabic_translation": 'روج التنوير للتحرير من خلال العقل.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Romantik idealisierte die Natur und das Individuum.', "english_translation": 'Romanticism idealized nature and the individual.', "arabic_translation": 'مثّلت الرومانسية الطبيعة والفرد.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Der Surrealismus verschmolz Traum und Wirklichkeit.', "english_translation": 'Surrealism merged dream and reality.', "arabic_translation": 'دمجت السريالية الحلم والواقع.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Barockliteratur zeichnet sich durch formale Komplexität aus.', "english_translation": 'Baroque literature is characterized by formal complexity.', "arabic_translation": 'يتميز الأدب الباروخي بالتعقيد الشكلي.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Weimarer Klassik strebte nach Harmonie und Maß.', "english_translation": 'Weimar Classicism strove for harmony and measure.', "arabic_translation": 'سعت الكلاسيكية فايمار إلى التوازن والاعتدال.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Naturalismus-Bewegung dokumentierte soziale Missstände.', "english_translation": 'The Naturalism movement documented social grievances.', "arabic_translation": 'وثّقت الحركة الطبيعية المظالم الاجتماعية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Avantgarde provozierte mit radikalen ästhetischen Konzepten.', "english_translation": 'The avant-garde provoked with radical aesthetic concepts.', "arabic_translation": 'استفزت الطليعة بمفاهيم جمالية جذرية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die intertextuellen Bezüge bereichern die literarische Analyse.', "english_translation": 'Intertextual references enrich literary analysis.', "arabic_translation": 'تُثري المراجع النصية المتداخلة التحليل الأدبي.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Theaterreform zielte auf eine authentischere Darstellung.', "english_translation": 'The theater reform aimed at a more authentic representation.', "arabic_translation": 'هدف إصلاح المسرح إلى تمثيل أكثر أصالة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Impressionistische Malerei fing flüchtige Lichtstimmungen ein.', "english_translation": 'Impressionist painting captured fleeting light moods.', "arabic_translation": 'التقطت اللوحة الانطباعية حالات ضوء عابرة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Kubistische Kunst zerlegte Objekte in geometrische Formen.', "english_translation": 'Cubist art decomposed objects into geometric shapes.', "arabic_translation": 'حلّل الفن التكعيبي الأشكال إلى أشكال هندسية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Dadaistische Bewegung lehnte bürgerliche Kunstvorstellungen ab.', "english_translation": 'The Dadaist movement rejected bourgeois art concepts.', "arabic_translation": 'رفضت الحركة الدادائية المفاهيم الفنية البرجوازية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Bauhaus-Schule vereinte Kunst und Funktionalität.', "english_translation": 'The Bauhaus school united art and functionality.', "arabic_translation": 'وحّدت مدرسة باوهاوس الفن والوظيفية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Pop Art reflektierte die Konsumgesellschaft.', "english_translation": 'Pop Art reflected consumer society.', "arabic_translation": 'عكس فن البوب مجتمع الاستهلاك.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Konzeptkunst stellte die Idee über das materielle Objekt.', "english_translation": 'Conceptual art placed the idea above the material object.', "arabic_translation": 'وضع الفن المفاهيمي الفكرة فوق الشيء المادي.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Musik des 20. Jahrhunderts experimentierte mit neuen Formen.', "english_translation": '20th century music experimented with new forms.', "arabic_translation": 'جرّب موسيقى القرن العشرين أشكالًا جديدة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Zwölftontechnik revolutionierte die Komposition.', "english_translation": 'The twelve-tone technique revolutionized composition.', "arabic_translation": 'أحدثت تقنية الاثني عشر نغمة ثورة في التأليف.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die minimalistische Kunst reduziert sich auf das Wesentliche.', "english_translation": 'Minimalist art reduces to the essential.', "arabic_translation": 'يُقلل الفن التبسيطي إلى الضروري.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Performance-Kunst überschreitet die Grenzen traditioneller Medien.', "english_translation": 'Performance art transcends the boundaries of traditional media.', "arabic_translation": 'يتجاوز فن الأداء حدود الوسائل التقليدية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die digitale Kunst nutzt neue Technologien als Ausdrucksmittel.', "english_translation": 'Digital art uses new technologies as a means of expression.', "arabic_translation": 'يستخدم الفن الرقمي التقنيات الجديدة كوسيلة تعبير.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Erzählperspektive bestimmt die Rezeption des Textes.', "english_translation": 'The narrative perspective determines the reception of the text.', "arabic_translation": 'يحدد منظور السرد استقبال النص.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Metaphorik verdichtet komplexe Zusammenhänge.', "english_translation": 'Metaphoric language condenses complex relationships.', "arabic_translation": 'تكثّف اللغة المجازية العلاقات المعقدة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Intertextualität schafft Dialoge zwischen Texten.', "english_translation": 'Intertextuality creates dialogues between texts.', "arabic_translation": 'يُحدث النصية المتداخلة حوارات بين النصوص.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Stream-of-Consciousness-Technik imitiert Gedankenflüsse.', "english_translation": 'Stream-of-consciousness technique imitates thought flows.', "arabic_translation": 'تُحاكي تقنية تيار الوعي تدفقات الأفكار.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die allegorische Darstellung veranschaulicht abstrakte Ideen.', "english_translation": 'Allegorical representation illustrates abstract ideas.', "arabic_translation": 'توضح التمثيل المجازي الأفكار المجردة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Ironie untergräbt die offensichtliche Bedeutung.', "english_translation": 'Irony undermines the obvious meaning.', "arabic_translation": 'تقوض السخرية المعنى الظاهر.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Tragödie thematisiert menschliche Abgründe.', "english_translation": 'Tragedy thematizes human abysses.', "arabic_translation": 'تتناول المأسأة الأعماق البشرية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Satire kritisiert gesellschaftliche Missstände mit Humor.', "english_translation": 'Satire criticizes social grievances with humor.', "arabic_translation": 'تنقد السخرية المظالم الاجتماعية بالفكاهة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Utopie entwirft eine idealisierte Zukunft.', "english_translation": 'Utopia designs an idealized future.', "arabic_translation": 'تصمم اليوتوبيا مستقبلًا مثاليًا.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Dystopie warnt vor gefährlichen Entwicklungen.', "english_translation": 'Dystopia warns of dangerous developments.', "arabic_translation": 'تحذر الديستوبيا من التطورات الخطيرة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Fabel vermittelt moralische Lehren durch Tiergeschichten.', "english_translation": 'The fable conveys moral lessons through animal stories.', "arabic_translation": 'تُنقل الخرافة الدروس الأخلاقية من خلال قصص الحيوانات.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Autobiographie reflektiert das eigene Leben kritisch.', "english_translation": "Autobiography critically reflects on one's own life.", "arabic_translation": 'يعكس السيرة الذاتية حياة المرء بشكل نقدي.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Poesie nutzt rhythmische und klangliche Mittel.', "english_translation": 'Poetry uses rhythmic and sonic devices.', "arabic_translation": 'يستخدم الشعر وسائل إيقاعية وصوتية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Dramaturgie strukturiert den Spannungsaufbau.', "english_translation": 'Dramaturgy structures the build-up of tension.', "arabic_translation": 'يُهيكل الدراماتورجي بناء التوتر.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Rezeptionsästhetik betont die Rolle des Lesers.', "english_translation": 'Reception aesthetics emphasizes the role of the reader.', "arabic_translation": 'يؤكد جماليات الاستقبال على دور القارئ.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die strukturalistische Analyse untersucht zugrunde liegende Muster.', "english_translation": 'Structuralist analysis examines underlying patterns.', "arabic_translation": 'يُفحص التحليل البنيوي الأنماط الأساسية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Semiotik erforscht Zeichensysteme und ihre Bedeutung.', "english_translation": 'Semiotics explores sign systems and their meaning.', "arabic_translation": 'يستكشف علم العلامات أنظمة العلامات ومعناها.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Narratologie untersucht die Struktur von Erzählungen.', "english_translation": 'Narratology examines the structure of narratives.', "arabic_translation": 'يدرس علم السرد بنية الحكايات.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Ästhetik des Hässlichen erweitert den Kunstbegriff.', "english_translation": 'The aesthetics of ugliness expands the concept of art.', "arabic_translation": 'يُوسع جماليات القبيح مفهوم الفن.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die kulturelle Aneignung ist ein kontroverses Thema.', "english_translation": 'Cultural appropriation is a controversial topic.', "arabic_translation": 'الاستيلاء الثقافي موضوع مثير للجدل.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Erinnerungskultur bewahrt historische Erfahrungen.', "english_translation": 'The culture of remembrance preserves historical experiences.', "arabic_translation": 'يحافظ ثقافة الذكرى التجارب التاريخية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Kulturerbe-Dokumentation sichert immaterielle Traditionen.', "english_translation": 'Cultural heritage documentation secures intangible traditions.', "arabic_translation": 'يُؤمن توثيق التراث الثقافي التقاليد غير المادية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die transkulturelle Literatur überschreitet nationale Grenzen.', "english_translation": 'Transcultural literature transcends national boundaries.', "arabic_translation": 'يتجاوز الأدب عبر الثقافي الحدود الوطنية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Gender Studies analysieren Geschlechterrollen kritisch.', "english_translation": 'Gender studies critically analyzes gender roles.', "arabic_translation": 'يحلل دراسات النوع الاجتماعي الأدوار الجندرية بشكل نقدي.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Kunstkritik bewertet Werke nach ästhetischen Kriterien.', "english_translation": 'Art criticism evaluates works according to aesthetic criteria.', "arabic_translation": 'يُقيّم النقد الفني الأعمال وفقًا لمعايير جمالية.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die Restaurierung bewahrt kulturelle Artefakte für die Nachwelt.', "english_translation": 'Restoration preserves cultural artifacts for posterity.', "arabic_translation": 'يحافظ الترميم القطع الأثرية الثقافية للأجيال القادمة.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die kuratorische Praxis gestaltet Ausstellungen narrativ.', "english_translation": 'Curatorial practice shapes exhibitions narratively.', "arabic_translation": 'يُشكّل الممارسة القيمية المعارض سرديًا.', "level": 'C1', "difficulty_score": 9, "category": 'Culture'},
    {"german_text": 'Die geopolitische Rivalität prägt die internationale Ordnung.', "english_translation": 'Geopolitical rivalry shapes the international order.', "arabic_translation": 'يُشكّل التنافس الجيوسياسي النظام الدولي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die multilaterale Diplomatie sucht konsensbasierte Lösungen.', "english_translation": 'Multilateral diplomacy seeks consensus-based solutions.', "arabic_translation": 'تسعى الدبلوماسية متعددة الأطراف إلى حلول قائمة على الإجماع.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Souveränitätsfrage ist im Zeitalter der Globalisierung komplex.', "english_translation": 'The question of sovereignty is complex in the age of globalization.', "arabic_translation": 'مسألة السيادة معقدة في عصر العولمة.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die humanitäre Intervention bleibt umstritten.', "english_translation": 'Humanitarian intervention remains controversial.', "arabic_translation": 'لا يزال التدخل الإنساني مثيرًا للجدل.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die nukleare Nichtverbreitung ist ein zentrales Sicherheitsanliegen.', "english_translation": 'Nuclear non-proliferation is a central security concern.', "arabic_translation": 'عدم انتشار الأسلحة النووية شغل أمني مركزي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Cybersicherheit wird zur nationalen Priorität.', "english_translation": 'Cybersecurity is becoming a national priority.', "arabic_translation": 'يُصبح الأمن السيبراني أولوية وطنية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Entwicklungszusammenarbeit fördert nachhaltige Strukturen.', "english_translation": 'Development cooperation promotes sustainable structures.', "arabic_translation": 'يعزز التعاون التنمية هياكل مستدامة.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Asylpolitik reflektiert humanitäre Verpflichtungen.', "english_translation": 'Asylum policy reflects humanitarian obligations.', "arabic_translation": 'تعكس سياسة اللجوء الالتزامات الإنسانية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Handelskriege destabilisieren die Weltwirtschaft.', "english_translation": 'Trade wars destabilize the world economy.', "arabic_translation": 'تُزعزع الحروب التجارية الاقتصاد العالمي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Sanktionspolitik dient als diplomatisches Druckmittel.', "english_translation": 'Sanctions policy serves as a diplomatic pressure tool.', "arabic_translation": 'تخدم سياسة العقوبات كأداة ضغط دبلوماسية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Friedensverhandlungen erfordern Kompromissbereitschaft.', "english_translation": 'Peace negotiations require willingness to compromise.', "arabic_translation": 'تتطلب مفاوضات السلام الاستعداد للتنازل.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die regionale Integration stärkt die politische Stabilität.', "english_translation": 'Regional integration strengthens political stability.', "arabic_translation": 'يعزز التكامل الإقليمي الاستقرار السياسي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Sicherheitsratsresolutionen sind völkerrechtlich bindend.', "english_translation": 'Security Council resolutions are binding under international law.', "arabic_translation": 'قرارات مجلس الأمن ملزمة بموجب القانون الدولي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Rüstungskontrolle reduziert das Konfliktpotenzial.', "english_translation": 'Arms control reduces conflict potential.', "arabic_translation": 'يُقلل الحد من التسلح إمكانات النزاع.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Soft Power beeinflusst durch kulturelle Attraktivität.', "english_translation": 'Soft power influences through cultural attractiveness.', "arabic_translation": 'يؤثر القوة الناعمة من خلال الجاذبية الثقافية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Machtbalance zwischen Großstaaten ist fragil.', "english_translation": 'The balance of power between major states is fragile.', "arabic_translation": 'توازن القوى بين الدول الكبرى هش.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Territorialkonflikte erschweren diplomatische Beziehungen.', "english_translation": 'Territorial conflicts complicate diplomatic relations.', "arabic_translation": 'تُعقّد النزاعات الإقليمية العلاقات الدبلوماسية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Energiegeopolitik bestimmt internationale Allianzen.', "english_translation": 'Energy geopolitics determines international alliances.', "arabic_translation": 'يحدد الجيوسياسة الطاقة التحالفات الدولية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Wasserressourcen werden zum strategischen Gut.', "english_translation": 'Water resources are becoming a strategic asset.', "arabic_translation": 'تُصبح موارد المياه أصلًا استراتيجيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Informationskriegsführung manipuliert öffentliche Meinung.', "english_translation": 'Information warfare manipulates public opinion.', "arabic_translation": 'تُلاعب الحرب المعلوماتية الرأي العام.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die globale Governance-Struktur ist reformbedürftig.', "english_translation": 'The global governance structure needs reform.', "arabic_translation": 'يحتاج هيكل الحوكمة العالمي إلى إصلاح.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Klimadiplomatie gewinnt an strategischer Bedeutung.', "english_translation": 'Climate diplomacy is gaining strategic importance.', "arabic_translation": 'يكتسب الدبلوماسية المناخية أهمية استراتيجية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Seewege sind von geostrategischer Relevanz.', "english_translation": 'Sea routes are of geostrategic relevance.', "arabic_translation": 'طرق البحر ذات أهمية جيواستراتيجية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Nahrungsmittelsicherheit ist eine globale Herausforderung.', "english_translation": 'Food security is a global challenge.', "arabic_translation": 'الأمن الغذائي تحدي عالمي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die digitale Souveränität wird zum politischen Ziel.', "english_translation": 'Digital sovereignty is becoming a political goal.', "arabic_translation": 'يُصبح السيادة الرقمية هدفًا سياسيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Migration verändert die demographische Zusammensetzung.', "english_translation": 'Migration changes the demographic composition.', "arabic_translation": 'يُغير الهجرة التكوين الديموغرافي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die internationale Strafjustiz verfolgt Kriegsverbrechen.', "english_translation": 'International criminal justice prosecutes war crimes.', "arabic_translation": 'تُحاكم العدالة الجنائية الدولية جرائم الحرب.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Abrüstungsverhandlungen stagnieren.', "english_translation": 'Disarmament negotiations are stagnating.', "arabic_translation": 'تتعثر مفاوضات نزع السلاح.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Bündnispolitik formt Sicherheitsarchitekturen.', "english_translation": 'Alliance policy shapes security architectures.', "arabic_translation": 'يُشكّل سياسة التحالف هياكل الأمن.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die wirtschaftliche Abhängigkeit erzeugt politische Verwundbarkeit.', "english_translation": 'Economic dependence creates political vulnerability.', "arabic_translation": 'يُحدث الاعتماد الاقتصادي ضعفًا سياسيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Wahlbeobachtungsmissionen stärken demokratische Prozesse.', "english_translation": 'Election observation missions strengthen democratic processes.', "arabic_translation": 'تُعزز بعثات مراقبة الانتخابات العمليات الديمقراطية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Sanktionsumgehung untergräbt internationale Maßnahmen.', "english_translation": 'Sanctions evasion undermines international measures.', "arabic_translation": 'يُضعف التحايل على العقوبات التدابير الدولية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die diplomatische Immunität schützt Vertreter ausländischer Staaten.', "english_translation": 'Diplomatic immunity protects representatives of foreign states.', "arabic_translation": 'يحمي الحصانة الدبلوماسية ممثلي الدول الأجنبية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Friedenssicherung erfordert langfristiges Engagement.', "english_translation": 'Peacekeeping requires long-term commitment.', "arabic_translation": 'يتطلب حفظ السلام التزامًا طويل المدى.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Völkerrechtsordnung basiert auf staatlicher Gleichheit.', "english_translation": 'The international legal order is based on state equality.', "arabic_translation": 'يُبنى النظام القانوني الدولي على المساواة بين الدول.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die humanitäre Hilfe unterliegt politischen Interessen.', "english_translation": 'Humanitarian aid is subject to political interests.', "arabic_translation": 'تخضع المساعدة الإنسانية للمصالح السياسية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die strategische Autonomie reduziert Abhängigkeiten.', "english_translation": 'Strategic autonomy reduces dependencies.', "arabic_translation": 'يُقلل الاستقلال الاستراتيجي الاعتماديات.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die multinationale Zusammenarbeit erfordert Kompromissfähigkeit.', "english_translation": 'Multinational cooperation requires ability to compromise.', "arabic_translation": 'يتطلب التعاون متعدد الجنسيات القدرة على التنازل.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die geopolitischen Verschiebungen verändern Machtverhältnisse.', "english_translation": 'Geopolitical shifts change power relations.', "arabic_translation": 'تُغير التحولات الجيوسياسية علاقات القوة.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Sicherheitsdilemmata erschweren vertrauensbildende Maßnahmen.', "english_translation": 'Security dilemmas complicate confidence-building measures.', "arabic_translation": 'تُعقّد معضلات الأمن تدابير بناء الثقة.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die internationale Ordnung befindet sich im Umbruch.', "english_translation": 'The international order is in transition.', "arabic_translation": 'النظام الدولي في مرحلة انتقالية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Ressourcenkonflikte verschärfen regionale Spannungen.', "english_translation": 'Resource conflicts intensify regional tensions.', "arabic_translation": 'تُشدّد النزاعات على الموارد التوترات الإقليمية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die diplomatische Kommunikation erfordert Fingerspitzengefühl.', "english_translation": 'Diplomatic communication requires tact.', "arabic_translation": 'يتطلب الاتصال الدبلوماسي لباقة.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Nuklearstrategie bestimmt sicherheitspolitische Doktrinen.', "english_translation": 'Nuclear strategy determines security policy doctrines.', "arabic_translation": 'تُحدد الاستراتيجية النووية عقائد السياسة الأمنية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die globale Ungleichheit untergräbt internationale Stabilität.', "english_translation": 'Global inequality undermines international stability.', "arabic_translation": 'يُضعف عدم المساواة العالمي الاستقرار الدولي.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die transnationale Bedrohungen erfordern koordinierte Antworten.', "english_translation": 'Transnational threats require coordinated responses.', "arabic_translation": 'تتطلب التهديدات العابرة للحدود الوطنية استجابات منسقة.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die außenpolitische Kontinuität schafft Verlässlichkeit.', "english_translation": 'Foreign policy continuity creates reliability.', "arabic_translation": 'يُحدث الاستمرارية في السياسة الخارجية موثوقية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Machtprojektion demonstriert militärische Fähigkeiten.', "english_translation": 'Power projection demonstrates military capabilities.', "arabic_translation": 'يُظهر إسقاط القوة القدرات العسكرية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die normative Kraft prägt internationale Standards.', "english_translation": 'Normative power shapes international standards.', "arabic_translation": 'يُشكّل القوة المعيارية المعايير الدولية.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die Krisenprävention ist kosteneffektiver als Intervention.', "english_translation": 'Crisis prevention is more cost-effective than intervention.', "arabic_translation": 'الوقاية من الأزمات أكثر فعالية من حيث التكلفة من التدخل.', "level": 'C1', "difficulty_score": 9, "category": 'Politics'},
    {"german_text": 'Die kognitive Dissonanz erzeugt psychisches Unbehagen.', "english_translation": 'Cognitive dissonance creates psychological discomfort.', "arabic_translation": 'يُحدث التنافر المعرفي انزعاجًا نفسيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Bindungstheorie erklärt frühe Beziehungsmuster.', "english_translation": 'Attachment theory explains early relationship patterns.', "arabic_translation": 'تُفسّر نظرية التعلق أنماط العلاقات المبكرة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Selbstwirksamkeitserwartung beeinflusst das Handeln.', "english_translation": 'Self-efficacy expectations influence behavior.', "arabic_translation": 'تؤثر توقعات الكفاءة الذاتية على السلوك.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Massenpsychologie untersucht kollektives Verhalten.', "english_translation": 'Mass psychology examines collective behavior.', "arabic_translation": 'يُفحص علم النفس الجماهيري السلوك الجماعي.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Traumaforschung hat therapeutische Ansätze revolutioniert.', "english_translation": 'Trauma research has revolutionized therapeutic approaches.', "arabic_translation": 'أحدث بحث الثورات ثورة في النهج العلاجية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Sozialisationsprozesse formen die Persönlichkeitsentwicklung.', "english_translation": 'Socialization processes shape personality development.', "arabic_translation": 'تُشكّل عمليات التنشئة الاجتماعية تطور الشخصية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Gruppendynamik beeinflusst Entscheidungsfindung.', "english_translation": 'Group dynamics influence decision-making.', "arabic_translation": 'تؤثر ديناميكا المجموعة على اتخاذ القرارات.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Resilienzforschung identifiziert Schutzfaktoren.', "english_translation": 'Resilience research identifies protective factors.', "arabic_translation": 'يُحدد بحث المرونة عوامل الحماية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Psychoanalyse erforscht das Unbewusste.', "english_translation": 'Psychoanalysis explores the unconscious.', "arabic_translation": 'يستكشف التحليل النفسي اللاوعي.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Verhaltensmodifikation nutzt Lerntheorien.', "english_translation": 'Behavior modification uses learning theories.', "arabic_translation": 'يستخدم تعديل السلوك نظريات التعلم.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Identitätskrise ist ein zentrales Konzept der Entwicklungspsychologie.', "english_translation": 'Identity crisis is a central concept in developmental psychology.', "arabic_translation": 'أزمة الهوية مفهوم مركزي في علم النفس التنموي.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Emotionsregulation ist entscheidend für psychische Gesundheit.', "english_translation": 'Emotion regulation is crucial for mental health.', "arabic_translation": 'تنظيم العواطف حاسم للصحة العقلية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Stereotypenforschung deckt implizite Vorurteile auf.', "english_translation": 'Stereotype research reveals implicit biases.', "arabic_translation": 'يكشف بحث الصور النمطية تحيزات ضمنية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Motivationstheorie erklärt Antriebskräfte menschlichen Handelns.', "english_translation": 'Motivation theory explains driving forces of human action.', "arabic_translation": 'تُفسّر نظرية الدافع القوى الدافعة للفعل البشري.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Wahrnehmungspsychologie untersucht sensorische Verarbeitung.', "english_translation": 'Perceptual psychology examines sensory processing.', "arabic_translation": 'يُفحص علم النفس الإدراكي المعالجة الحسية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Sozialpsychologie erforscht Gruppenverhalten und Einstellungen.', "english_translation": 'Social psychology explores group behavior and attitudes.', "arabic_translation": 'يستكشف علم النفس الاجتماعي سلوك المجموعة والمواقف.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Burnout-Prävention ist ein wichtiges gesellschaftliches Anliegen.', "english_translation": 'Burnout prevention is an important social concern.', "arabic_translation": 'الوقاية من الاحتراق الوظيفي شاغل اجتماعي مهم.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die psychosomatische Medizin verbindet Körper und Psyche.', "english_translation": 'Psychosomatic medicine connects body and mind.', "arabic_translation": 'يربط الطب النفسي الجسدي بين الجسم والعقل.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Entwicklungspsychologie begleitet den gesamten Lebenszyklus.', "english_translation": 'Developmental psychology accompanies the entire life cycle.', "arabic_translation": 'يرافق علم النفس التنموي دورة الحياة الكاملة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Tiefenpsychologie erforscht verdrängte Konflikte.', "english_translation": 'Depth psychology explores repressed conflicts.', "arabic_translation": 'يستكشف علم النفس العميق الصراعات المكبوتة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Positiven Psychologie fokussiert auf menschliche Stärken.', "english_translation": 'Positive psychology focuses on human strengths.', "arabic_translation": 'يركز علم النفس الإيجابي على نقاط القوة البشرية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Kommunikationspsychologie analysiert Interaktionsmuster.', "english_translation": 'Communication psychology analyzes interaction patterns.', "arabic_translation": 'يُحلل علم نفس الاتصال أنماط التفاعل.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Suchtpsychologie untersucht Abhängigkeitsmechanismen.', "english_translation": 'Addiction psychology examines dependency mechanisms.', "arabic_translation": 'يُفحص علم نفس الإدمان آليات الاعتماد.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Differentielle Psychologie erforscht individuelle Unterschiede.', "english_translation": 'Differential psychology explores individual differences.', "arabic_translation": 'يستكشف علم النفس الفروقي الفروق الفردية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Arbeitspsychologie optimiert Arbeitsbedingungen.', "english_translation": 'Work psychology optimizes working conditions.', "arabic_translation": 'يُحسّن علم نفس العمل ظروف العمل.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Forensische Psychologie begutachtet im rechtlichen Kontext.', "english_translation": 'Forensic psychology assesses in a legal context.', "arabic_translation": 'يُقيّم علم النفس الشرعي في السياق القانوني.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Gesundheitspsychologie fördert präventives Verhalten.', "english_translation": 'Health psychology promotes preventive behavior.', "arabic_translation": 'يعزز علم النفس الصحي السلوك الوقائي.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Pädagogische Psychologie verbessert Lehr-Lern-Prozesse.', "english_translation": 'Educational psychology improves teaching-learning processes.', "arabic_translation": 'يُحسّن علم النفس التربوي عمليات التعليم والتعلم.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Verkehrspsychologie untersucht Fahrverhalten und Sicherheit.', "english_translation": 'Traffic psychology examines driving behavior and safety.', "arabic_translation": 'يُفحص علم نفس المرور سلوك القيادة والسلامة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Kulturpsychologie vergleicht psychologische Prozesse über Kulturen.', "english_translation": 'Cultural psychology compares psychological processes across cultures.', "arabic_translation": 'يقارن علم النفس الثقافي العمليات النفسية عبر الثقافات.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Evolutionspsychologie erklärt Verhalten durch adaptive Mechanismen.', "english_translation": 'Evolutionary psychology explains behavior through adaptive mechanisms.', "arabic_translation": 'يُفسّر علم النفس التطوري السلوك من خلال آليات تكيفية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Neuropsychologie verbindet Gehirnstrukturen mit Verhalten.', "english_translation": 'Neuropsychology connects brain structures with behavior.', "arabic_translation": 'يربط علم النفس العصبي هياكل الدماغ بالسلوك.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Persönlichkeitspsychologie kategorisiert individuelle Merkmale.', "english_translation": 'Personality psychology categorizes individual traits.', "arabic_translation": 'يُصنّف علم نفس الشخصية السمات الفردية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Entscheidungsforschung analysiert kognitive Verzerrungen.', "english_translation": 'Decision research analyzes cognitive biases.', "arabic_translation": 'يُحلل بحث القرار التحيزات المعرفية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Empathieforschung untersucht die Fähigkeit zum Perspektivenwechsel.', "english_translation": 'Empathy research examines the ability to change perspectives.', "arabic_translation": 'يُفحص بحث التعاطف القدرة على تغيير المنظور.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Stressbewältigungsstrategien variieren je nach Persönlichkeit.', "english_translation": 'Stress coping strategies vary by personality.', "arabic_translation": 'تختلف استراتيجيات التعامل مع الإجهاد حسب الشخصية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Gruppendenken-Phänomene führen zu fehlerhaften Entscheidungen.', "english_translation": 'Groupthink phenomena lead to faulty decisions.', "arabic_translation": 'تؤدي ظواهر تفكير المجموعة إلى قرارات خاطئة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Achtsamkeitspraxis reduziert nachweislich Stress.', "english_translation": 'Mindfulness practice demonstrably reduces stress.', "arabic_translation": 'يُقلل ممارسة اليقظة الذهنية الإجهاد بشكل مثبت.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Psycholinguistik erforscht den Zusammenhang von Sprache und Denken.', "english_translation": 'Psycholinguistics explores the relationship between language and thought.', "arabic_translation": 'يستكشف علم النفس اللغوي العلاقة بين اللغة والتفكير.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Tiefenstruktur der Persönlichkeit bleibt weitgehend unbewusst.', "english_translation": 'The deep structure of personality remains largely unconscious.', "arabic_translation": 'يظل البنية العميقة للشخصية إلى حد كبير غير واعية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die kognitive Verhaltenstherapie ist empirisch gut belegt.', "english_translation": 'Cognitive behavioral therapy is well-supported empirically.', "arabic_translation": 'العلاج السلوكي المعرفي مدعوم تجريبيًا بشكل جيد.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die interpersonelle Kommunikation unterliegt nonverbalen Signalen.', "english_translation": 'Interpersonal communication is subject to nonverbal signals.', "arabic_translation": 'يخضع الاتصال الشخصي لإشارات غير لفظية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die psychologische Erstbetreuung hilft in akuten Krisen.', "english_translation": 'Psychological first aid helps in acute crises.', "arabic_translation": 'تساعد الإسعافات النفسية الأولية في الأزمات الحادة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Sozialisation durch Medien prägt Wertevorstellungen.', "english_translation": 'Socialization through media shapes value concepts.', "arabic_translation": 'يُشكّل التنشئة الاجتماعية من خلال الإعلام مفاهيم القيم.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Selbstkonzeptforschung untersucht die Identitätsbildung.', "english_translation": 'Self-concept research examines identity formation.', "arabic_translation": 'يُفحص بحث مفهوم الذات تكوين الهوية.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Konfliktlösung erfordert emotionale Intelligenz.', "english_translation": 'Conflict resolution requires emotional intelligence.', "arabic_translation": 'يتطلب حل النزاعات الذكاء العاطفي.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die psychologische Diagnostik verwendet standardisierte Verfahren.', "english_translation": 'Psychological diagnostics uses standardized procedures.', "arabic_translation": 'يستخدم التشخيص النفسي إجراءات موحدة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Resilienzförderung stärkt die psychische Widerstandskraft.', "english_translation": 'Resilience promotion strengthens psychological resilience.', "arabic_translation": 'يعزز تعزيز المرونة القدرة النفسية على المقاومة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die Bewältigungsmechanismen variieren je nach Stressor.', "english_translation": 'Coping mechanisms vary depending on the stressor.', "arabic_translation": 'تختلف آليات التعامل حسب المسبب.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die psychosoziale Beratung unterstützt in Lebenskrisen.', "english_translation": 'Psychosocial counseling supports in life crises.', "arabic_translation": 'يدعم الاستشارة النفسية الاجتماعية في أزمات الحياة.', "level": 'C1', "difficulty_score": 9, "category": 'Psychology'},
    {"german_text": 'Die konstruktivistische Lerntheorie betont aktive Wissenskonstruktion.', "english_translation": 'Constructivist learning theory emphasizes active knowledge construction.', "arabic_translation": 'تؤكد نظرية التعلم البنائية على بناء المعرفة النشط.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die formative Evaluation begleitet den Lernprozess kontinuierlich.', "english_translation": 'Formative evaluation accompanies the learning process continuously.', "arabic_translation": 'يرافق التقييم التكويني عملية التعلم بشكل مستمر.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die metakognitive Strategie fördert selbstreguliertes Lernen.', "english_translation": 'The metacognitive strategy promotes self-regulated learning.', "arabic_translation": 'يعزز الاستراتيجية فوق المعرفية التعلم المنظم ذاتيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die kompetenzorientierte Didaktik ersetzt die inputorientierte Lehre.', "english_translation": 'Competence-oriented didactics replaces input-oriented teaching.', "arabic_translation": 'تحل الديداكتيكا الموجهة نحو الكفاءة محل التدريس الموجه نحو المدخلات.', "level": 'C1', "difficulty_score": 10, "category": 'Education'},
    {"german_text": 'Die Scaffolding-Methode unterstützt schrittweise Kompetenzentwicklung.', "english_translation": 'The scaffolding method supports gradual competence development.', "arabic_translation": 'يدعم طريقة السقالات تطوير الكفاءة تدريجيًا.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Lerntransfer-Theorie erklärt die Anwendung von Wissen in neuen Kontexten.', "english_translation": 'Learning transfer theory explains the application of knowledge in new contexts.', "arabic_translation": 'تُفسّر نظرية نقل التعلم تطبيق المعرفة في سياقات جديدة.', "level": 'C1', "difficulty_score": 10, "category": 'Education'},
    {"german_text": 'Die differenzielle Förderung berücksichtigt individuelle Lernvoraussetzungen.', "english_translation": 'Differentiated instruction considers individual learning prerequisites.', "arabic_translation": 'يأخذ التعليم المتمايز في الاعتبار المتطلبات التعليمية الفردية.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die curriculare Progression strukturiert den Kompetenzzuwachs.', "english_translation": 'Curricular progression structures competence growth.', "arabic_translation": 'يُهيكل التقدم المناهجي نمو الكفاءة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Peer-Instruction-Methode aktiviert die Lernenden.', "english_translation": 'The peer instruction method activates learners.', "arabic_translation": 'يُفعّل طريقة تعليم الأقران المتعلمين.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Flipped-Classroom-Modelle verlagern Wissensvermittlung nach Hause.', "english_translation": 'Flipped classroom models shift knowledge transfer to home.', "arabic_translation": 'يُنقل نماذج الفصل المعكوس نقل المعرفة إلى المنزل.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Diagnostik von Lernschwierigkeiten erfordert präzise Instrumente.', "english_translation": 'Diagnosing learning difficulties requires precise instruments.', "arabic_translation": 'يتطلب تشخيص صعوبات التعلم أدوات دقيقة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die professionelle Weiterbildung aktualisiert fachliche Kompetenzen.', "english_translation": 'Professional continuing education updates subject-specific competencies.', "arabic_translation": 'يُحدّث التعليم المهني المستمر الكفاءات المتخصصة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Bildungsforschung evidenzbasiert pädagogische Entscheidungen.', "english_translation": 'Educational research provides evidence-based pedagogical decisions.', "arabic_translation": 'يُؤسّس البحث التربوي القرارات التربوية على الأدلة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die inklusive Didaktik adaptiert Unterricht für alle Lernenden.', "english_translation": 'Inclusive didactics adapts instruction for all learners.', "arabic_translation": 'يُكيّف الديداكتيكا الشاملة التدريس لجميع المتعلمين.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Lernmotivation wird durch Autonomieerleben gesteigert.', "english_translation": 'Learning motivation is increased through experiencing autonomy.', "arabic_translation": 'يُزاد الدافع التعليمي من خلال تجربة الاستقلالية.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Unterrichtsforschung optimiert Lehr-Lern-Interaktionen.', "english_translation": 'Classroom research optimizes teaching-learning interactions.', "arabic_translation": 'يُحسّن بحث الفصل التفاعلات التعليمية التعلمية.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Kompetenzraster visualisieren Lernfortschritte.', "english_translation": 'Competence grids visualize learning progress.', "arabic_translation": 'تُصور شبكات الكفاءة تقدم التعلم.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Selbstreflexion ist zentral für professionelle Entwicklung.', "english_translation": 'Self-reflection is central to professional development.', "arabic_translation": 'التأمل الذاتي مركزي للتطور المهني.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Bildungsgerechtigkeit erfordert strukturelle Reformen.', "english_translation": 'Educational equity requires structural reforms.', "arabic_translation": 'يتطلب العدالة التعليمية إصلاحات هيكلية.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Lernumgebungsgestaltung beeinflusst den Lernerfolg.', "english_translation": 'Learning environment design influences learning success.', "arabic_translation": 'يُؤثر تصميم بيئة التعلم على نجاح التعلم.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Begabtenförderung fordert spezifische pädagogische Konzepte.', "english_translation": 'Gifted education requires specific pedagogical concepts.', "arabic_translation": 'يتطلب تعليم الموهوبين مفاهيم تربوية محددة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Schulleitungsforschung untersucht Führungsstile.', "english_translation": 'School leadership research examines leadership styles.', "arabic_translation": 'يُفحص بحث القيادة المدرسية أنماط القيادة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Professionalisierung der Lehrkräfte ist ein kontinuierlicher Prozess.', "english_translation": 'Teacher professionalization is a continuous process.', "arabic_translation": 'إضفاء الطابع المهني على المعلمين عملية مستمرة.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Lernstandsdiagnose ermöglicht gezielte Förderung.', "english_translation": 'Learning status diagnosis enables targeted support.', "arabic_translation": 'يُمكّن تشخيص حالة التعلم الدعم المستهدف.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Unterrichtsentwicklung folgt datengestützten Erkenntnissen.', "english_translation": 'Instructional development follows data-driven insights.', "arabic_translation": 'يتبع تطوير التدريس رؤى قائمة على البيانات.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Feedback-Kultur verbessert die Lernergebnisse.', "english_translation": 'Feedback culture improves learning outcomes.', "arabic_translation": 'يُحسّن ثقافة التغذية الراجعة نتائج التعلم.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
    {"german_text": 'Die Schulinspektion evaluiert Bildungsqualität.', "english_translation": 'School inspection evaluates educational quality.', "arabic_translation": 'يُقيّم التفتيش المدرسي جودة التعليم.', "level": 'C1', "difficulty_score": 9, "category": 'Education'},
