# Insert in batches of 100
session = SessionLocal()
try:
    for i in range(0, len(sentences), 100):
        batch = sentences[i:i+100]
        sentence_objects = [Sentence(**s) for s in batch]
        session.bulk_save_objects(sentence_objects)
        session.commit()
        print(f'Inserted {min(i+100, len(sentences))}/{len(sentences)} sentences...')
    print(f'Successfully seeded {len(sentences)} sentences!')
except Exception as e:
    session.rollback()
    print(f"Error: {e}")
    raise
finally:
    session.close()
